  ko_genus = excluded.ko_genus,
  en_genus = excluded.en_genus,
  generation = excluded.generation,
  category = excluded.category,
  type1 = excluded.type1,
  type2 = excluded.type2,
  hp = excluded.hp,
  attack = excluded.attack,
  defense = excluded.defense,
  special_attack = excluded.special_attack,
  special_defense = excluded.special_defense,
  speed = excluded.speed,
  height = excluded.height,
  weight = excluded.weight,
  growth_rate = excluded.growth_rate,
  capture_rate = excluded.capture_rate,
  hatch_counter = excluded.hatch_counter,
  gender_rate = excluded.gender_rate,
  evolves_from_id = excluded.evolves_from_id,
  evolution_method = excluded.evolution_method,
  sprites = excluded.sprites;

insert into public.pokedex_kinds (id, ko_name, en_name) values
  ('unova', '하나도감', 'Unova Pokédex')
on conflict (id) do update set
  ko_name = excluded.ko_name,
  en_name = excluded.en_name;

insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 494, 494, true, '비크티니가 무한히 만들어내는 에너지를 나누어 받으면 전신에 파워가 넘친다.', 'When it shares the infinite energy it creates, that being’s entire body will be overflowing with power.'),
  ('national', 495, 495, true, '꼬리로 태양의 빛을 받아 광합성한다. 기운이 빠지면 꼬리가 축 늘어진다.', 'They photosynthesize by bathing their tails in sunlight. When they are not feeling well, their tails droop.'),
  ('national', 496, 496, true, '몸이 더러워지면 잎으로 광합성을 할 수 없기 때문에 항상 청결하게 하고 있다.', 'When it gets dirty, its leaves can’t be used in photosynthesis, so it always keeps itself clean.'),
  ('national', 497, 497, true, '째려보기만 해도 상대의 움직임을 멈추게 한다. 태양에너지를 체내에서 증폭시킨다.', 'It can stop its opponents’ movements with just a glare. It takes in solar energy and boosts it internally.'),
  ('national', 498, 498, true, '구운 나무열매를 먹는 것을 매우 좋아하지만 너무 흥분해서 가끔 새까맣게 태워버린다.', 'It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.'),
  ('national', 499, 499, true, '체내의 불꽃이 타오르면 움직임이 더 빠르고 예리해진다. 위급해지면 연기를 뿜어낸다.', 'When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.'),
  ('national', 500, 500, true, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
  ('national', 501, 501, true, '배에 있는 가리비칼로 싸운다. 공격을 막고 그 즉시 베어 반격한다.', 'This Pokémon from the Unova region uses the shell on its belly as a weapon to cut down its foes. Thus, I''ve conferred upon this shell the name ”scalchop”.'),
  ('national', 502, 502, true, '혹독한 수행 끝에 쌍검자비마다 다른 형태의 가리비칼 다루는 기술을 습득한다.', 'Its exquisite double-scalchop technique is likely the result of daily training, and it can send even masters of the blade fleeing in defeat.'),
  ('national', 503, 503, true, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
  ('national', 504, 504, true, '경계심이 강해서 반드시 한 마리는 망을 보고 있으나 뒤에서 오는 상대는 알아차리지 못한다.', 'Extremely cautious, one of them will always be on the lookout, but it won’t notice a foe coming from behind.'),
  ('national', 505, 505, true, '뺨의 주머니에 모아둔 나무열매의 씨앗을 날려서 공격한다. 적을 발견하면 꼬리를 세운다.', 'When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.'),
  ('national', 506, 506, true, '또래의 아이보다 훨씬 영리하다. 사랑받은 것도 혼난 것도 잊지 않는다.', 'This Pokémon is far brighter than the average child, and Lillipup won’t forget the love it receives or any abuse it suffers.'),
  ('national', 507, 507, true, '몸을 뒤덮은 검은 털은 두껍고 탄력이 있다. 날카로운 이빨도 튕겨낸다.', 'The black fur that covers this Pokémon’s body is dense and springy. Even sharp fangs bounce right off.'),
  ('national', 508, 508, true, '훌륭한 수염이 특징인 포켓몬이다. 그 길이로 동료들과 우열을 가린다고 한다.', 'Stoutland is immensely proud of its impressive moustache. It’s said that moustache length is what determines social standing among this species.'),
  ('national', 509, 509, true, '귀여운 동작으로 방심시키고 상대가 다가오면 갑자기 발톱으로 할퀴고는 웃는다.', 'Opponents that get drawn in by its adorable behavior come away with stinging scratches from its claws and stinging pride from its laughter.'),
  ('national', 510, 510, true, '폭슬라이와 영역을 두고 다툰다. 소리를 전혀 내지 않고 먹이의 배후에 접근한다.', 'This stealthy Pokémon sneaks up behind prey without making any sound at all. It competes with Thievul for territory.'),
  ('national', 511, 511, true, '나무열매를 잘 찾아 여기저기에서 모아 동료에게 나누어 주는 상냥함을 가졌다.', 'It’s good at finding berries and gathers them from all over. It’s kind enough to share them with friends.'),
  ('national', 512, 512, true, '기질이 격하여 가시가 박힌 꼬리를 휘두르며 싸운다. 머리의 잎사귀는 매우 쓰다.', 'Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.'),
  ('national', 513, 513, true, '화산 동굴에서 산다. 머리의 송아리 속이 불타고 있어 300도나 되는 높은 온도가 된다.', 'This Pokémon lives in caves in volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.'),
  ('national', 514, 514, true, '흥분하면 머리나 꼬리에서 불티가 날아올라 뜨거워진다. 왜인지 달콤한 것을 매우 좋아한다.', 'When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.'),
  ('national', 515, 515, true, '머리의 송아리에 모은 물은 영양이 가득하다. 식물에 뿌려주면 크게 자란다.', 'The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large.'),
  ('national', 516, 516, true, '물이 깨끗한 장소를 좋아한다. 머리에 모아둔 물이 줄어들면 꼬리에서 빨아올려 보급한다.', 'It prefers places with clean water. When its tuft runs low, it replenishes it by siphoning up water with its tail.'),
  ('national', 517, 517, true, '꿈을 먹고 연기를 내뿜는다. 즐거운 꿈이면 핑크색이고 악몽이면 거무스름하다.', 'It eats dreams and releases mist. The mist is pink when it’s eating a good dream, and black when it’s eating a nightmare.'),
  ('national', 518, 518, true, '언제나 선잠을 자며 꿈을 꾼다. 잠에서 깨면 매우 불쾌해하므로 가만히 내버려 두자.', 'It drowses and dreams all the time. It’s best to leave it be if it’s just woken up, as it’s a terrible grump when freshly roused from sleep.'),
  ('national', 519, 519, true, '건망증이 심하고 영리하지 않지만 사람을 잘 따르고 착실해서 귀여워하는 트레이너가 많다.', 'It’s forgetful and not very bright, but many Trainers love it anyway for its friendliness and sincerity.'),
  ('national', 520, 520, true, '영리하고 기억력이 좋다. 배달원이 파트너로 선택하는 경우가 많다.', 'These bright Pokémon have acute memories. Apparently delivery workers often choose them as their partners.'),
  ('national', 521, 521, true, '영리한 만큼 프라이드도 높다. 켄호로우의 트레이너가 되면 모두에게 실력을 인정받는다.', 'This Pokémon is intelligent and intensely proud. People will sit up and take notice if you become the Trainer of one.'),
  ('national', 522, 522, true, '방전하면 갈기가 빛난다. 갈기가 빛나는 횟수나 리듬으로 동료와 대화한다.', 'Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.'),
  ('national', 523, 523, true, '천둥번개 같은 순발력을 가지고 있다. 제브라이카가 전속력으로 달리면 천둥소리가 울려 퍼진다.', 'They have lightning-like movements. When Zebstrika run at full speed, the sound of thunder reverberates.'),
  ('national', 524, 524, true, '소리에 반응해 움직인다. 에너지 코어의 영향으로 만지면 조금 따듯하다.', 'When it detects a noise, it starts to move. The energy core inside it makes this Pokémon slightly warm to the touch.'),
  ('national', 525, 525, true, '소리로 주위 상황을 살핀다. 화나게 하면 몸의 방향을 바꾸지 않은 채로 쫓아온다.', 'It relies on sound in order to monitor what’s in its vicinity. When angered, it will attack without ever changing the direction it’s facing.'),
  ('national', 526, 526, true, '맑은 날에만 쏠 수 있지만 에너지탄의 파괴력은 덤프트럭도 날려버릴 정도다.', 'Although its energy blasts can blow away a dump truck, they have a limitation— they can only be fired when the sun is out.'),
  ('national', 527, 527, true, '초음파를 발산하면서 흔들흔들 날아다닌다. 먹이인 벌레포켓몬을 찾고 있다.', 'It emits ultrasonic waves as it flutters about, searching for its prey—bug Pokémon.'),
  ('national', 528, 528, true, '코의 모양이 복스럽다고 행복을 부르는 상징으로 여기는 지역도 있다고 한다.', 'The auspicious shape of this Pokémon’s nose apparently led some regions to consider Swoobat a symbol of good luck.'),
  ('national', 529, 529, true, '손톱으로 땅속을 파고 다니면서 키우는 채소를 해치기 때문에 농업 종사자들이 싫어한다.', 'It’s a digger, using its claws to burrow through the ground. It causes damage to vegetable crops, so many farmers have little love for it.'),
  ('national', 530, 530, true, '별명은 드릴킹이다. 땅속을 파는 속도는 시속 150km에 달한다.', 'Known as the Drill King, this Pokémon can tunnel through the terrain at speeds of over 90 mph.'),
  ('national', 531, 531, true, '마음 착한 포켓몬이다. 더듬이를 갖다 대어 상대의 마음과 몸 상태를 파악한다.', 'This Pokémon has a kind heart. By touching with its feelers, Audino can gauge other creatures’ feelings and physical conditions.'),
  ('national', 532, 532, true, '자신의 3배 정도의 각목을 들 수 있게 된 으랏차는 머지않아 진화하게 된다.', 'Timburr that have started carrying logs that are about three times their size are nearly ready to evolve.'),
  ('national', 533, 533, true, '철골을 자유자재로 다룬다. 해체는 잘하지만 무언가를 조립하는 것은 서툴다.', 'Gurdurr excels at demolition—construction is not its forte. In any case, there’s skill in the way this Pokémon wields its metal beam.'),
  ('national', 534, 534, true, '정말 싸울 생각이면 콘크리트 기둥을 버리고 주먹 하나로 상대를 노리고 덤벼든다.', 'When going all out, this Pokémon throws aside its concrete pillars and leaps at opponents to pummel them with its fists.'),
  ('national', 535, 535, true, '음파로 동료와 연락한다. 경계하는 울음소리는 사람이나 다른 포켓몬에게 들리지 않는다.', 'It uses sound waves to communicate with others of its kind. People and other Pokémon species can’t hear its cries of warning.'),
  ('national', 536, 536, true, '고운 목소리로 울 때도 있다. 몸의 돌기가 클수록 넓은 음역으로 울 수 있다.', 'On occasion, their cries are sublimely pleasing to the ear. Palpitoad with larger lumps on their bodies can sing with a wider range of sounds.'),
  ('national', 537, 537, true, '혹이 일으키는 바이브레이션이 마사지에 좋다고 노인에게 인기가 높은 포켓몬이다.', 'This Pokémon is popular among the elderly, who say the vibrations of its lumps are great for massages.'),
  ('national', 538, 538, true, '5마리의 무리가 수련한다. 수련에 뒤떨어지면 띠를 버리고 무리를 떠난다.', 'They train in groups of five. Any member that can’t keep up will discard its belt and leave the group.'),
  ('national', 539, 539, true, '단련하고 단련한 타격귀가 사용하는 필살 태권당수는 바다도 가를 정도의 파괴력을 지녔다.', 'The karate chops of a Sawk that’s trained itself to the limit can cleave the ocean itself.'),
  ('national', 540, 540, true, '잎사귀로 옷을 만들기 때문에 패션 디자이너에게 마스코트로 인기가 있다.', 'Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.'),
  ('national', 541, 541, true, '잎사귀로 몸을 감싸 추위를 막는다. 가까이 있는 낙엽을 먹으며 숲을 이동한다.', 'It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.'),
  ('national', 542, 542, true, '낙엽이 발효되는 열로 알을 따뜻하게 한다. 잎사귀로 두르보의 포대기를 만든다.', 'It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.'),
  ('national', 543, 543, true, '이빨에 맹독을 지녔다. 먹을 수 있는 먹이를 발견하면 앞뒤를 가리지 않고 덤벼든다.', 'Its fangs are highly venomous. If this Pokémon finds prey it thinks it can eat, it leaps for them without any thought of how things might turn out.'),
  ('national', 544, 544, true, '단단한 껍질과 독가시로 몸을 보호하면서 진화에 필요한 에너지를 비축하고 있다.', 'Whirlipede protects itself with a sturdy shell and poisonous spikes while it stores up the energy it’ll need for evolution.'),
  ('national', 545, 545, true, '영역을 두고 다태우지네와 격렬하게 다툰다. 패배한 쪽이 그대로 먹이가 된다.', 'Scolipede engage in fierce territorial battles with Centiskorch. At the end of one of these battles, the victor makes a meal of the loser.'),
  ('national', 546, 546, true, '소미안과 백솜모카의 솜을 섞어 짠 천은 아름다워서 고급 브랜드에 사용된다.', 'Weaving together the cotton of both Cottonee and Eldegoss produces exquisite cloth that’s highly prized by many luxury brands.'),
  ('national', 547, 547, true, '햇빛을 받을수록 솜이 부풀어 오른다. 너무 부풀면 찢어져 주위로 흩어진다.', 'As long as this Pokémon bathes in sunlight, its cotton keeps growing. If too much cotton fluff builds up, Whimsicott tears it off and scatters it.'),
  ('national', 548, 548, true, '잎사귀의 색이 짙을수록 건강하다. 잘 정돈된 밭이나 화단에 자리잡고 살기도 한다.', 'The leaves on its head are highly valued for medicinal purposes. Dry the leaves in the sun, boil them, and then drink the bitter decoction for remarkably effective relief from fatigue.'),
  ('national', 549, 549, true, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
  ('national', 550, 550, true, '옛날에는 식탁에 올랐다. 적색근 배쓰나이의 살코기는 기름이 많아 젊은 층이 좋아한다.', 'Though it differs from other Basculin in several respects, including demeanor—this one is gentle—I have categorized it as a regional form given the vast array of shared qualities.'),
  ('national', 550, 10066, false, '옛날에는 식탁에 올랐다. 적색근 배쓰나이의 살코기는 기름이 많아 젊은 층이 좋아한다.', 'Though it differs from other Basculin in several respects, including demeanor—this one is gentle—I have categorized it as a regional form given the vast array of shared qualities.'),
  ('national', 551, 551, true, '작지만 하체의 힘은 세다. 모래를 헤치며 사막을 헤엄치듯 이동한다.', 'Sandile is small, but its legs and lower body are powerful. Pushing sand aside as it goes, Sandile moves through the desert as if it’s swimming.'),
  ('national', 552, 552, true, '어둠 속에서도 볼 수 있는 특수한 눈을 가졌지만 사막의 밤은 춥기 때문에 잘 움직이지 않는다.', 'Although this Pokémon has specialized eyes that allow it to see in the dark, Krokorok won’t move much at night—the desert gets cold after sunset.'),
  ('national', 553, 553, true, '난폭하지만 먹이를 잡기 위해 모래 속에서 며칠이든 기다리는 강한 인내력도 갖고 있다.', 'While terribly aggressive, Krookodile also has the patience to stay hidden under sand for days, lying in wait for prey.'),
  ('national', 554, 554, true, '자고 있을 때는 밀어도 당겨도 절대 쓰러지지 않는다. 길조의 모티브로 인기가 높다.', 'This popular symbol of good fortune will never fall over in its sleep, no matter how it’s pushed or pulled.'),
  ('national', 555, 555, true, '체내의 불꽃이 타오를수록 파워가 올라간다. 그 온도는 1400도를 넘기도 한다.', 'This Pokémon’s power level rises along with the temperature of its fire, which can reach 2,500 degrees Fahrenheit.'),
  ('national', 555, 10067, false, '체내의 불꽃이 타오를수록 파워가 올라간다. 그 온도는 1400도를 넘기도 한다.', 'This Pokémon’s power level rises along with the temperature of its fire, which can reach 2,500 degrees Fahrenheit.'),
  ('national', 556, 556, true, '일 년에 한 번 씨를 뿌린다. 꽃의 씨는 영양이 매우 풍부해 사막의 귀중한 식량이다.', 'Once each year, this Pokémon scatters its seeds. They’re jam-packed with nutrients, making them a precious food source out in the desert.'),
  ('national', 557, 557, true, '집으로 삼기 딱 좋은 돌멩이를 발견하지 못하면 하마돈의 구멍에 살기도 한다.', 'It first tries to find a rock to live in, but if there are no suitable rocks to be found, Dwebble may move in to the ports of a Hippowdon.'),
  ('national', 558, 558, true, '두꺼운 발톱이 최고의 무기다. 거대코뿌리의 프로텍터조차 금이 갈 정도로 딱딱하다.', 'Its thick claws are its greatest weapons. They’re mighty enough to crack Rhyperior’s carapace.'),
  ('national', 559, 559, true, '튼튼한 가죽으로 몸을 지킨다. 가죽이 다 늘어나면 진화할 때가 되었다고 한다.', 'It protects itself with its durable skin. It’s thought that this Pokémon will evolve once its skin has completely stretched out.'),
  ('national', 560, 560, true, '매우 거친 성격이지만 가족과 동료와 영역은 소중히 여긴다.', 'While mostly known for having the temperament of an aggressive ruffian, this Pokémon takes very good care of its family, friends, and territory.'),
  ('national', 561, 561, true, '심보러가 나는 사막 아래를 조사해 보니 고대 도시로 여겨지는 자취가 발견되었다.', 'A discovery was made in the desert where Sigilyph fly. The ruins of what may have been an ancient city were found beneath the sands.'),
  ('national', 562, 562, true, '고대인의 영혼이 포켓몬이 되어 태어났다. 자신의 얼굴을 아는 사람을 찾아 유적을 떠돈다.', 'The spirit of a person from a bygone age became this Pokémon. It rambles through ruins, searching for someone who knows its face.'),
  ('national', 563, 563, true, '오래된 묘지의 벽을 보면 왕의 부를 드러내고자 그려져 있는 경우가 많다.', 'There are many depictions of Cofagrigus decorating ancient tombs. They’re symbols of the wealth that kings of bygone eras had.'),
  ('national', 564, 564, true, '많은 거북포켓몬의 선조로 여겨지고 있는 포켓몬이다. 화석에서 복원되었다.', 'Tirtouga is considered to be the ancestor of many turtle Pokémon. It was restored to life from a fossil.'),
  ('national', 565, 565, true, '물속과 비교하면 움직임이 둔하지만 먹이를 찾아 육지에서도 활동한다.', 'This Pokémon emerges from the water in search of prey despite the fact that it moves more slowly on land.'),
  ('national', 566, 566, true, '새포켓몬의 선조로 불린다. 나무 위에서 살며 나무열매나 벌레포켓몬을 먹는다.', 'Archen is said to be the ancestor of bird Pokémon. It lived in treetops, eating berries and bug Pokémon.'),
  ('national', 567, 567, true, '비행도 가능하지만 지상에서 먹이를 사냥하는 일을 훨씬 더 잘하는 듯하다.', 'Though capable of flight, Archeops was apparently better at hunting on the ground.'),
  ('national', 568, 568, true, '쓰레기가 가득 담긴 쓰레기봉투에서 태어났다. 내뿜는 독가스는 가라르의 또도가스가 매우 좋아한다.', 'This Pokémon was born from a bag stuffed with trash. Galarian Weezing relish the fumes belched by Trubbish.'),
  ('national', 569, 569, true, '오른팔에서 내보내는 독액은 약한 생물이 맞으면 즉사할 정도로 위험하다.', 'The toxic liquid it launches from its right arm is so virulent that it can kill a weakened creature instantly.'),
  ('national', 570, 570, true, '먹이를 찾아 사람으로 둔갑하여 마을에 나타나기도 한다. 주로 아이로 둔갑한다.', 'A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, Zorua vents lingering malice.'),
  ('national', 571, 571, true, '고독한 트레이너는 조로아크에게 환상을 보여주도록 명령하여 혼자만의 외로움을 달랜다.', 'With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, Zoroark attacks its nemeses with a bitter energy so intense, it lacerates Zoroark''s own body.'),
  ('national', 572, 572, true, '꼬리로 쓰다듬으며 서로 인사한다. 꼬리 털이 많은 쪽이 조금 으스댄다.', 'They pet each other with their tails as a form of greeting. Of the two, the one whose tail is fluffier is a bit more boastful.'),
  ('national', 573, 573, true, '특별한 기름이 스며든 털은 공격을 받아넘긴다. 기름은 높은 가격에 거래되고 있다.', 'A special oil that seeps through their fur helps them avoid attacks. The oil fetches a high price at market.'),
  ('national', 574, 574, true, '아무도 없는데 나직이 운다. 고디탱에게만 보이는 뭔가와 이야기하는 듯하다.', 'Even when nobody seems to be around, Gothita can still be heard making a muted cry. Many believe it’s speaking to something only it can see.'),
  ('national', 575, 575, true, '별이 빛나는 밤에 가장 사이코 파워가 높아지는 듯하다. 우주와의 관계는 불명확하다.', 'On nights when the stars shine, this Pokémon’s psychic power is at its strongest. It’s unknown just what link Gothorita has to the greater universe.'),
  ('national', 576, 576, true, '고디모아젤을 통해 자신의 최후를 보게 된 악인은 그날을 마지막으로 종적을 감추었다.', 'A criminal who was shown his fate by a Gothitelle went missing that same day and was never seen again.'),
  ('national', 577, 577, true, '특수한 액체로 몸을 둘러싸고 있어 우주에서도 살 수 있다고 전해진다.', 'Many say that the special liquid covering this Pokémon’s body would allow it to survive in the vacuum of space.'),
  ('national', 578, 578, true, '분열한 2개의 뇌는 생각이 거의 일치하지 않아 전혀 행동을 예측할 수 없다.', 'Its brain has split into two, and the two halves rarely think alike. Its actions are utterly unpredictable.'),
  ('national', 579, 579, true, '특수한 액체를 마시면 지혜를 얻는다고 전해지지만 란쿨루스 외에는 맹독이다.', 'It’s said that drinking the liquid surrounding Reuniclus grants wisdom. Problem is, the liquid is highly toxic to anything besides Reuniclus itself.'),
  ('national', 580, 580, true, '나는 것보다 헤엄치는 것이 특기로 수중에 잠수해서는 제일 좋아하는 물이끼를 기쁘게 먹는다.', 'They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.'),
  ('national', 581, 581, true, '새벽이 오면 스완나들이 춤추기 시작한다. 한가운데에서 춤추는 스완나가 무리의 우두머리다.', 'Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.'),
  ('national', 582, 582, true, '고드름에서 태어났다고 전해진다. 마이너스 50도의 냉기를 뿜어 주변을 얼려 살기 좋게 만든다.', 'Supposedly, this Pokémon was born from an icicle. It spews out freezing air at −58 degrees Fahrenheit to make itself more comfortable.'),
  ('national', 583, 583, true, '마이너스 100도의 냉기로 적을 얼리지만 목숨은 뺏지 않는 상냥한 기질을 가졌다.', 'It blasts enemies with cold air reaching −148 degrees Fahrenheit, freezing them solid. But it spares their lives afterward—it’s a kind Pokémon.'),
  ('national', 584, 584, true, '체온은 마이너스 6도 전후이다. 2마리의 바닐리치가 붙어서 태어났다고 한다.', 'People believe this Pokémon formed when two Vanillish stuck together. Its body temperature is roughly 21 degrees Fahrenheit.'),
  ('national', 585, 585, true, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'The turning of the seasons changes the color and scent of this Pokémon’s fur. People use it to mark the seasons.'),
  ('national', 585, 10068, false, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'The turning of the seasons changes the color and scent of this Pokémon’s fur. People use it to mark the seasons.'),
  ('national', 585, 10069, false, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'The turning of the seasons changes the color and scent of this Pokémon’s fur. People use it to mark the seasons.'),
  ('national', 585, 10070, false, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'The turning of the seasons changes the color and scent of this Pokémon’s fur. People use it to mark the seasons.'),
  ('national', 586, 586, true, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('national', 586, 10071, false, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('national', 586, 10072, false, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('national', 586, 10073, false, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('national', 587, 587, true, '달콤한 나무열매를 매우 좋아한다. 볼주머니에 먹이를 너무 많이 넣어 잘 날지 못할 때도 있다.', 'This Pokémon absolutely loves sweet berries. Sometimes it stuffs its cheeks full of so much food that it can’t fly properly.'),
  ('national', 588, 588, true, '입에서 내뿜는 액체로 쪼마리의 껍질을 녹여서 내용물만 먹어 치운다.', 'It spits a liquid from its mouth to melt through Shelmet’s shell. Karrablast doesn’t eat the shell— it eats only the contents.'),
  ('national', 589, 589, true, '창을 겨누고 적에게 돌격한다. 창파나이트와의 결투를 그린 그림이 유명하다.', 'It charges its enemies, lances at the ready. An image of one of its duels is captured in a famous painting of Escavalier clashing with Sirfetch’d.'),
  ('national', 590, 590, true, '양손에서 내뿜는 포자는 맹독이지만 잘 말리면 복통약이 된다고 한다.', 'The spores released from this Pokémon’s hands are highly poisonous, but when thoroughly dried, the spores can be used as stomach medicine.'),
  ('national', 591, 591, true, '평상시에는 잘 움직이지 않는다. 떨어져 있는 몬스터볼 옆에서 그저 가만히 대기할 뿐이다.', 'Amoonguss generally doesn’t move much. It tends to stand still near Poké Balls that have been dropped on the ground.'),
  ('national', 592, 592, true, '해저에 가라앉은 고대 도시의 주민이 포켓몬이 되었다는 전설이 남아 있다.', 'Legend has it that the residents of a sunken ancient city changed into these Pokémon.'),
  ('national', 593, 593, true, '보름달이 뜨면 무리를 거느리고 해수면에 모습을 드러낸다. 먹이가 오기를 기다리는 것이다.', 'Whenever a full moon hangs in the night sky, schools of Jellicent gather near the surface of the sea, waiting for their prey to appear.'),
  ('national', 594, 594, true, '약해진 포켓몬을 도와주는 것은 이를 노리고 오는 포켓몬에게 자신도 공격받기 때문이라고 한다.', 'The reason it helps Pokémon in a weakened condition is that any Pokémon coming after them may also attack Alomomola.'),
  ('national', 595, 595, true, '다른 포켓몬에게 달라붙어 정전기를 빨아들인다. 멍파치의 엉덩이에 자주 달라붙어 있다.', 'Joltik latch on to other Pokémon and suck out static electricity. They’re often found sticking to Yamper’s hindquarters.'),
  ('national', 596, 596, true, '잘 날지 못하는 새끼를 노리고 새포켓몬 둥지 가까이에 전기로 된 실로 함정을 만든다.', 'It lays traps of electrified threads near the nests of bird Pokémon, aiming to snare chicks that are not yet good at flying.'),
  ('national', 597, 597, true, '이끼 낀 동굴을 좋아한다. 이끼에 함유된 효소가 가시를 크고 튼튼하게 만들어준다.', 'Mossy caves are their preferred dwellings. Enzymes contained in mosses help Ferroseed’s spikes grow big and strong.'),
  ('national', 598, 598, true, '강철보다 견고한 가시를 갖고 있다. 촉수 가시를 찔러서 바위 벽을 기어 다니며 이동한다.', 'Its spikes are harder than steel. This Pokémon crawls across rock walls by stabbing the spikes on its feelers into the stone.'),
  ('national', 599, 599, true, '먼 옛날에 기어르를 본 사람이 톱니바퀴의 구조를 고안했다고 전해진다.', 'It’s suspected that Klink were the inspiration behind ancient people’s invention of the first gears.'),
  ('national', 600, 600, true, '공업 기술의 상징으로 많은 가라르의 회사에서 기업 로고로 채용하고 있다.', 'Many companies in the Galar region choose Klang as their logo. This Pokémon is considered the symbol of industrial technology.'),
  ('national', 601, 601, true, '3개의 기어가 고속 회전한다. 가시가 달려 있는 새로 생긴 기어는 생물이 아니다.', 'The three gears that compose this Pokémon spin at high speed. Its new spiked gear isn’t a living creature.'),
  ('national', 602, 602, true, '약한 전기밖에 낼 수 없어 많은 저리어가 모여서 강력한 전기를 발산한다.', 'One alone can emit only a trickle of electricity, so a group of them gathers to unleash a powerful electric shock.'),
  ('national', 603, 603, true, '식욕이 왕성한 포켓몬이다. 먹이를 발견하면 덮쳐서 전기로 마비시킨 후 먹는다.', 'These Pokémon have a big appetite. When they spot their prey, they attack it and paralyze it with electricity.'),
  ('national', 604, 604, true, '팔 힘으로 바다에서 기어 나와 물가에 있는 먹이를 덮친다. 한순간에 바다로 끌고 들어간다.', 'They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean.'),
  ('national', 605, 605, true, '약 50년 전에 발견된 포켓몬이다. 크게 발달한 뇌로 사이코 파워를 조종한다.', 'This Pokémon was discovered about 50 years ago. Its highly developed brain enables it to exert its psychic powers.'),
  ('national', 606, 606, true, '상대의 기억을 조작할 수 있다. 보리밭 위를 떠도는 모습이 가끔 목격된다.', 'Sometimes found drifting above wheat fields, this Pokémon can control the memories of its opponents.'),
  ('national', 607, 607, true, '흡수하는 생명이 젊으면 젊을수록 머리의 불꽃은 크고 괴이하게 타오른다.', 'The younger the life this Pokémon absorbs, the brighter and eerier the flame on its head burns.'),
  ('national', 608, 608, true, '램프인 척 마을 안으로 숨어든다. 죽음이 다가온 사람을 발견하면 조용히 뒤를 쫓는다.', 'It lurks in cities, pretending to be a lamp. Once it finds someone whose death is near, it will trail quietly after them.'),
  ('national', 609, 609, true, '샹델라를 등불 대용으로 사용했던 저택에서는 장례식이 끊이지 않았다고 한다.', 'In homes illuminated by Chandelure instead of lights, funerals were a constant occurrence— or so it’s said.'),
  ('national', 610, 610, true, '커다란 어금니를 부딪치며 동료와 장난친다. 어금니는 부러져도 바로 자라나서 걱정 없다.', 'They play with each other by knocking their large tusks together. Their tusks break sometimes, but they grow back so quickly that it isn’t a concern.'),
  ('national', 611, 611, true, '갑옷처럼 딱딱한 피부를 가졌다. 몸통박치기와 동시에 어금니로 찌르는 전법이 특기다.', 'Its skin is as hard as a suit of armor. Fraxure’s favorite strategy is to tackle its opponents, stabbing them with its tusks at the same time.'),
  ('national', 612, 612, true, '온화한 성격이지만 화가 나면 무섭다. 철골도 베어 가르는 튼튼한 어금니를 보여 줄 것이다.', 'While usually kindhearted, it can be terrifying if angered. Tusks that can slice through steel beams are how Haxorus deals with its adversaries.'),
  ('national', 613, 613, true, '기술을 사용하기 전에 코를 훌쩍인다. 콧물에 포함된 강한 냉기가 얼음 기술의 근원이다.', 'It sniffles before performing a move, using its frosty snot to provide an icy element to any move that needs it.'),
  ('national', 614, 614, true, '차가운 바다에서 씩씩하게 헤엄친다. 지치면 한숨을 내쉬어 바다를 얼린 뒤 그 위에서 쉰다.', 'It swims energetically through frigid seas. When it gets tired, it freezes the seawater with its breath so it can rest on the ice.'),
  ('national', 615, 615, true, '뜨거워지면 수증기로 변한다. 여름철에 모습을 볼 일은 거의 없다.', 'When the weather gets hot, these Pokémon turn into water vapor. Cryogonal are almost never seen during summer.'),
  ('national', 616, 616, true, '전기 에너지에 반응하는 신비한 체질을 지녔다. 딱정곤과 함께 있으면 무슨 이유인지 진화한다.', 'It has a strange physiology that responds to electricity. When together with Karrablast, Shelmet evolves for some reason.'),
  ('national', 617, 617, true, '껍질을 벗어 몸이 가벼워졌다. 띠 형태의 점막을 몸에 둘러 건조해지는 것을 방지한다.', 'Discarding its shell made it nimble. To keep itself from dehydrating, it wraps its body in bands of membrane.'),
  ('national', 618, 618, true, '몸의 노란 무늬에서 강한 전기를 발산할 때 무슨 이유인지 살짝 웃고 있다.', 'For some reason, this Pokémon smiles slightly when it emits a strong electric current from the yellow markings on its body.'),
  ('national', 619, 619, true, '작아도 기질은 거칠다. 방심하고 다가간 상대에게 화려한 연타를 먹인다.', 'Though small, Mienfoo’s temperament is fierce. Any creature that approaches Mienfoo carelessly will be greeted with a flurry of graceful attacks.'),
  ('national', 620, 620, true, '눈에 보이지 않을 정도의 스피드로 구사하는 발차기는 거대한 바위도 산산이 조각낸다.', 'Delivered at blinding speeds, kicks from this Pokémon can shatter massive boulders into tiny pieces.'),
  ('national', 621, 621, true, '난폭하고 교활하다. 다른 포켓몬이 파낸 굴을 빼앗아 거처로 삼는다.', 'Druddigon are vicious and cunning. They take up residence in nests dug out by other Pokémon, treating the stolen nests as their own lairs.'),
  ('national', 622, 622, true, '점토로 만들어진 포켓몬이다. 수천 년 전 주인의 명령을 지금도 따르고 있다.', 'This Pokémon was created from clay. It received orders from its master many thousands of years ago, and it still follows those orders to this day.'),
  ('national', 623, 623, true, '체내에 에너지를 생성하는 영구 기관이 있다고 하지만 아직도 밝혀지지 않았다.', 'There’s a theory that inside Golurk is a perpetual motion machine that produces limitless energy, but this belief hasn’t been proven.'),
  ('national', 624, 624, true, '절각참을 보스로 둔 무리를 만든다. 무리를 이끄는 날을 꿈꾸며 날마다 단련을 계속한다.', 'A pack of these Pokémon forms to serve a Bisharp boss. Each Pawniard trains diligently, dreaming of one day taking the lead.'),
  ('national', 625, 625, true, '칼날을 가는 돌의 장소를 두고 액슨도와 격렬하게 싸움을 벌인다.', 'Violent conflicts erupt between Bisharp and Fraxure over places where sharpening stones can be found.'),
  ('national', 626, 626, true, '20마리 정도가 무리 지어 산다. 무리를 배신한 버프론은 어째서인지 머리털이 빠진다.', 'These Pokémon live in herds of about 20 individuals. Bouffalant that betray the herd will lose the hair on their heads for some reason.'),
  ('national', 627, 627, true, '딱딱한 나무열매도 산산조각 내는 악력을 가졌다. 쉽게 다투고 아무에게나 승부를 건다.', 'Its chick-like looks belie its hotheadedness. It challenges its parents at every opportunity, desperate to prove its strength.'),
  ('national', 628, 628, true, '혈기왕성하고 거칠어서 가라르의 배달부 자리는 아머까오에게 뺏겼다.', 'Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water''s surface.'),
  ('national', 629, 629, true, '금방 크게 성장하므로 엉덩이의 해골은 둥지 안에서 대물림되어 계속 사용된다.', 'Vullaby grow quickly. Bones that have gotten too small for older Vullaby to wear often get passed down to younger ones in the nest.'),
  ('national', 630, 630, true, '주운 뼈로 몸을 장식한다. 몸에 두르는 뼈의 모양은 유행이 있는 듯하다.', 'They adorn themselves with bones. There seem to be fashion trends among them, as different bones come into and fall out of popularity.'),
  ('national', 631, 631, true, '불꽃을 혀처럼 사용한다. 아이앤트의 단단한 외골격을 조금씩 녹여 먹어 치운다.', 'A flame serves as its tongue, melting through the hard shell of Durant so that Heatmor can devour their insides.'),
  ('national', 632, 632, true, '큰 턱은 암석도 깨물어 부순다. 사다이사로부터 알을 지키기 위해 무리 지어 싸운다.', 'With their large mandibles, these Pokémon can crunch their way through rock. They work together to protect their eggs from Sandaconda.'),
  ('national', 633, 633, true, '눈이 보이지 않아 닥치는 대로 물면서 본인 주위의 상황을 파악한다.', 'Because it can’t see, this Pokémon is constantly biting at everything it touches, trying to keep track of its surroundings.'),
  ('national', 634, 634, true, '1개의 먹이를 2개의 머리가 서로 뺏는다. 누구랑 싸운 것도 아닌데 언제나 상처투성이다.', 'Their two heads will fight each other over a single piece of food. Zweilous are covered in scars even without battling others.'),
  ('national', 635, 635, true, '3개의 머리로 번갈아 가며 물어뜯는다. 상대가 쓰러질 때까지 공격을 멈추지 않는다.', 'The three heads take turns sinking their teeth into the opponent. Their attacks won’t slow until their target goes down.'),
  ('national', 636, 636, true, '전신이 제법 따뜻하다. 뿔 끝에서 불꽃을 뿜어 천적이나 먹이를 위협한다.', 'Larvesta’s body is warm all over. It spouts fire from the tips of its horns to intimidate predators and scare prey.'),
  ('national', 637, 637, true, '활활 타오르는 불의 고치에서 태어났다. 고대의 벽화에 불꽃의 신으로 그려져 있다.', 'This Pokémon emerges from a cocoon formed of raging flames. Ancient murals depict Volcarona as a deity of fire.'),
  ('national', 638, 638, true, '태어나면서부터 리더의 품격을 몸에 지녔다. 흉포한 상대도 코바르온의 앞에서는 온순하다.', 'From the moment it’s born, this Pokémon radiates the air of a leader. Its presence will calm even vicious foes.'),
  ('national', 639, 639, true, '포켓몬을 지키기 위해 사람에게 승부를 걸었다는 전설이 하나지방에 남아 있다.', 'In Unovan legend, Terrakion battled against humans in an effort to protect other Pokémon.'),
  ('national', 640, 640, true, '회오리바람처럼 재빠른 몸동작으로 적을 농락하고 예리한 뿔로 가차 없이 베어버린다.', 'It darts around opponents with a flurry of quick movements, slicing them up with its horns.'),
  ('national', 641, 641, true, '토네로스의 꼬리에서 뿜어져 나온 에너지가 큰 폭풍을 일으킨다. 민가를 날려버릴 정도의 힘이다.', 'This storm-stirring Pokémon is said to cause the seasons to turn by whipping up the air. I suspect its humanlike form to be a false one.'),
  ('national', 641, 10079, false, '토네로스의 꼬리에서 뿜어져 나온 에너지가 큰 폭풍을 일으킨다. 민가를 날려버릴 정도의 힘이다.', 'This storm-stirring Pokémon is said to cause the seasons to turn by whipping up the air. I suspect its humanlike form to be a false one.'),
  ('national', 642, 642, true, '넓은 하늘을 날아다니며 여기저기 번개를 떨어뜨려 산불을 내기 때문에 미움받는다.', 'They say this wielder of electricity has waged war with its nemesis, Tornadus, since time immemorial. The lightning bolts it hurls pierce the very earth and enrich the soil.'),
  ('national', 642, 10080, false, '넓은 하늘을 날아다니며 여기저기 번개를 떨어뜨려 산불을 내기 때문에 미움받는다.', 'They say this wielder of electricity has waged war with its nemesis, Tornadus, since time immemorial. The lightning bolts it hurls pierce the very earth and enrich the soil.'),
  ('national', 643, 643, true, '사람이 진실을 모른 체하고 욕심으로 가득 차면 불꽃으로 나라를 태워버린다는 신화가 있다.', 'According to myth, if people ignore truth and let themselves become consumed by greed, Reshiram will arrive to burn their kingdoms down.'),
  ('national', 644, 644, true, '사람이 올바른 마음을 잃으면 격렬한 천둥으로 나라를 멸망시킨다는 신화가 있다.', 'Mythology tells us that if people lose the righteousness in their hearts, their kingdoms will be razed by Zekrom’s lightning.'),
  ('national', 645, 645, true, '바람이나 번개를 거둬들여 바꾼 에너지가 흙에 영양을 주어 대지를 풍족하게 한다.', 'When the incarnations of wind and of lightning clash, Landorus arrives to quell the conflict. After the tempests and thunderbolts abate, the land is sure to be blessed with bountiful harvests.'),
  ('national', 645, 10081, false, '바람이나 번개를 거둬들여 바꾼 에너지가 흙에 영양을 주어 대지를 풍족하게 한다.', 'When the incarnations of wind and of lightning clash, Landorus arrives to quell the conflict. After the tempests and thunderbolts abate, the land is sure to be blessed with bountiful harvests.'),
  ('national', 646, 646, true, '세포 조직을 안정시키기 위해 자신이 발생시킨 냉기로 몸을 얼어붙게 한 듯하다.', 'It appears that this Pokémon uses its powers over ice to freeze its own body in order to stabilize its cellular structure.'),
  ('national', 646, 10082, false, '세포 조직을 안정시키기 위해 자신이 발생시킨 냉기로 몸을 얼어붙게 한 듯하다.', 'It appears that this Pokémon uses its powers over ice to freeze its own body in order to stabilize its cellular structure.'),
  ('national', 646, 10083, false, '세포 조직을 안정시키기 위해 자신이 발생시킨 냉기로 몸을 얼어붙게 한 듯하다.', 'It appears that this Pokémon uses its powers over ice to freeze its own body in order to stabilize its cellular structure.'),
  ('national', 647, 647, true, '혹독한 싸움을 이겨내고 이마의 뿔이 단련되면 진정한 힘이 각성한다고 한다.', 'They say that Keldeo must survive harsh battles and fully develop the horn on its forehead before this Pokémon’s true power will awaken.'),
  ('national', 647, 10084, false, '혹독한 싸움을 이겨내고 이마의 뿔이 단련되면 진정한 힘이 각성한다고 한다.', 'They say that Keldeo must survive harsh battles and fully develop the horn on its forehead before this Pokémon’s true power will awaken.'),
  ('national', 648, 648, true, '특수한 발성법으로 노래하는 멜로디는 노래를 들은 자의 감정을 자유자재로 조종한다.', 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.'),
  ('national', 648, 10074, false, '특수한 발성법으로 노래하는 멜로디는 노래를 들은 자의 감정을 자유자재로 조종한다.', 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.'),
  ('national', 649, 649, true, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('national', 649, 10075, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('national', 649, 10076, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('national', 649, 10077, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('national', 649, 10078, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('unova', 0, 494, true, '비크티니가 무한히 만들어내는 에너지를 나누어 받으면 전신에 파워가 넘친다.', 'When it shares the infinite energy it creates, that being’s entire body will be overflowing with power.'),
  ('unova', 1, 495, true, '꼬리로 태양의 빛을 받아 광합성한다. 기운이 빠지면 꼬리가 축 늘어진다.', 'Being exposed to sunlight makes its movements swifter. It uses vines more adeptly than its hands.'),
  ('unova', 2, 496, true, '몸이 더러워지면 잎으로 광합성을 할 수 없기 때문에 항상 청결하게 하고 있다.', 'When it gets dirty, its leaves can’t be used in photosynthesis, so it always keeps itself clean.'),
  ('unova', 3, 497, true, '째려보기만 해도 상대의 움직임을 멈추게 한다. 태양에너지를 체내에서 증폭시킨다.', 'It only gives its all against strong opponents who are not fazed by the glare from Serperior’s noble eyes.'),
  ('unova', 4, 498, true, '구운 나무열매를 먹는 것을 매우 좋아하지만 너무 흥분해서 가끔 새까맣게 태워버린다.', 'It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.'),
  ('unova', 5, 499, true, '체내의 불꽃이 타오르면 움직임이 더 빠르고 예리해진다. 위급해지면 연기를 뿜어낸다.', 'The more it eats, the more fuel it has to make the fire in its stomach stronger. This fills it with even more power.'),
  ('unova', 6, 500, true, '불꽃 턱수염을 기르고 있다. 파워와 스피드를 겸비한 격투 기술을 익히고 있다.', 'A flaring beard of fire is proof that it is fired up. It is adept at using many different moves.'),
  ('unova', 7, 501, true, '배에 있는 가리비칼로 싸운다. 공격을 막고 그 즉시 베어 반격한다.', 'The scalchop on its stomach isn’t just used for battle--it can be used to break open hard berries as well.'),
  ('unova', 8, 502, true, '혹독한 수행 끝에 쌍검자비마다 다른 형태의 가리비칼 다루는 기술을 습득한다.', 'As a result of strict training, each Dewott learns different forms for using the scalchops.'),
  ('unova', 9, 503, true, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'In the time it takes a foe to blink, it can draw and sheathe the seamitars attached to its front legs.'),
  ('unova', 10, 504, true, '경계심이 강해서 반드시 한 마리는 망을 보고 있으나 뒤에서 오는 상대는 알아차리지 못한다.', 'Extremely cautious, one of them will always be on the lookout, but it won’t notice a foe coming from behind.'),
  ('unova', 11, 505, true, '뺨의 주머니에 모아둔 나무열매의 씨앗을 날려서 공격한다. 적을 발견하면 꼬리를 세운다.', 'Using luminescent matter, it makes its eyes and body glow and stuns attacking opponents.'),
  ('unova', 12, 509, true, '귀여운 동작으로 방심시키고 상대가 다가오면 갑자기 발톱으로 할퀴고는 웃는다.', 'Their cute act is a ruse. They trick people and steal their valuables just to see the looks on their faces.'),
  ('unova', 13, 510, true, '폭슬라이와 영역을 두고 다툰다. 소리를 전혀 내지 않고 먹이의 배후에 접근한다.', 'Their beautiful form comes from the muscles they have developed. They run silently in the night.'),
  ('unova', 14, 519, true, '건망증이 심하고 영리하지 않지만 사람을 잘 따르고 착실해서 귀여워하는 트레이너가 많다.', 'This very forgetful Pokémon will wait for a new order from its Trainer even though it already has one.'),
  ('unova', 15, 520, true, '영리하고 기억력이 좋다. 배달원이 파트너로 선택하는 경우가 많다.', 'No matter where in the world it goes, it knows where its nest is, so it never gets separated from its Trainer.'),
  ('unova', 16, 521, true, '영리한 만큼 프라이드도 높다. 켄호로우의 트레이너가 되면 모두에게 실력을 인정받는다.', 'Males swing the plumage on their heads to threaten others, but females are better at flying.'),
  ('unova', 17, 540, true, '잎사귀로 옷을 만들기 때문에 패션 디자이너에게 마스코트로 인기가 있다.', 'Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.'),
  ('unova', 18, 541, true, '잎사귀로 몸을 감싸 추위를 막는다. 가까이 있는 낙엽을 먹으며 숲을 이동한다.', 'Preferring dark, damp places, it spends the entire day eating fallen leaves that lie around it.'),
  ('unova', 19, 542, true, '낙엽이 발효되는 열로 알을 따뜻하게 한다. 잎사귀로 두르보의 포대기를 만든다.', 'Upon finding a small Pokémon, it weaves clothing for it from leaves by using the sticky silk secreted from its mouth.'),
  ('unova', 20, 191, true, '몸에 모은 영양을 진화할 때까지 간직하기 위해 거의 움직이려 하지 않는다. 아무것도 먹지 않고 아침 이슬만 마시고 있다.', 'It suddenly falls out of the sky in the morning. Knowing it’s weak, it simply feeds until it evolves.'),
  ('unova', 21, 192, true, '태양 에너지에서 영양을 만들어낸다. 기온이 높은 낮에는 활발하게 움직이고 태양이 지면 뚝 하니 움직이지 않게 된다.', 'Since it converts sunlight into energy, it is always looking in the direction of the sun.'),
  ('unova', 22, 506, true, '또래의 아이보다 훨씬 영리하다. 사랑받은 것도 혼난 것도 잊지 않는다.', 'Though it is a very brave Pokémon, it’s also smart enough to check its foe’s strength and avoid battle.'),
  ('unova', 23, 507, true, '몸을 뒤덮은 검은 털은 두껍고 탄력이 있다. 날카로운 이빨도 튕겨낸다.', 'This very loyal Pokémon helps Trainers, and it also takes care of other Pokémon.'),
  ('unova', 24, 508, true, '훌륭한 수염이 특징인 포켓몬이다. 그 길이로 동료들과 우열을 가린다고 한다.', 'Being wrapped in its long fur is so comfortable that a person would be fine even overnight on a wintry mountain.'),
  ('unova', 25, 179, true, '솜털이 마찰하여 전기가 모인다. 귀엽다고 맨손으로 만지면 따끔하게 저리고 아프다.', 'When cold weather increases static electricity, its wool doubles in size and the tip of its tail glows slightly.'),
  ('unova', 26, 180, true, '푹신푹신한 털에 전기를 저장한다. 너무 많이 저장해서 여기저기 반질반질하게 털이 빠져 버렸다.', 'Not even downy wool will grow on its rubbery, nonconductive patches of skin that prevent electrical shock.'),
  ('unova', 27, 181, true, '꼬리는 강하고 밝게 빛난다. 뱃사람들의 길잡이로서 옛날부터 소중히 여겨져 왔다.', 'The tip of its tail shines so brightly it can be used to send sea-navigation beacons to distant foreign shores.'),
  ('unova', 28, 54, true, '스트레스가 쌓이면 두통이 심해진다. 강력한 염동력으로 주위를 압도한다.', 'When headaches stimulate its brain cells, which are usually inactive, it can use a mysterious power.'),
  ('unova', 29, 55, true, '강을 더럽힌 사람을 물속으로 끌어들여 데려간다는 옛날이야기가 전해져 오고 있다.', 'When its forehead shines mysteriously, Golduck can use the full extent of its power.'),
  ('unova', 30, 298, true, '얌전한 포켓몬이지만 화가 나면 꼬리의 큰 공을 붕붕 휘두르다 세차게 내리친다.', 'It swings its large, nutrient-filled tail around to fight opponents bigger than itself.'),
  ('unova', 31, 183, true, '물을 잘 튕겨내는 털은 차가운 바다에 있다가 나와도 금방 말라서 춥지 않다.', 'The oil-filled tail functions as a buoy, so it’s fine even in rivers with strong currents.'),
  ('unova', 32, 184, true, '공기로 가득 찬 거품을 만든다. 루리리가 강에서 놀 때는 이 거품으로 감싸준다.', 'Its long ears are superb sensors. It can distinguish the movements of things in water and tell what they are.'),
  ('unova', 33, 447, true, '상대의 감정뿐만 아니라 자연의 상태도 파동이라는 파장의 형태로 느낀다.', 'It uses the shapes of auras, which change according to emotion, to communicate with others.'),
  ('unova', 34, 448, true, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'By reading the auras of all things, it can tell how others are feeling from over half a mile away.'),
  ('unova', 35, 206, true, '미로 같은 굴에 산다. 흙냄새로 자신이 있는 곳을 알 수 있어 절대 길을 잃지 않는다.', 'It creates mazes in dark locations. When spotted, it flees into the ground by digging with its tail.'),
  ('unova', 36, 531, true, '마음 착한 포켓몬이다. 더듬이를 갖다 대어 상대의 마음과 몸 상태를 파악한다.', 'Using the feelers on its ears, it can tell how someone is feeling or when an egg might hatch.'),
  ('unova', 37, 511, true, '나무열매를 잘 찾아 여기저기에서 모아 동료에게 나누어 주는 상냥함을 가졌다.', 'It’s good at finding berries and gathers them from all over. It’s kind enough to share them with friends.'),
  ('unova', 38, 512, true, '기질이 격하여 가시가 박힌 꼬리를 휘두르며 싸운다. 머리의 잎사귀는 매우 쓰다.', 'It strikes its enemies with a thorn-covered tail. The leaf on its head is bitter.'),
  ('unova', 39, 513, true, '화산 동굴에서 산다. 머리의 송아리 속이 불타고 있어 300도나 되는 높은 온도가 된다.', 'Very intelligent, it roasts berries before eating them. It likes to help people.'),
  ('unova', 40, 514, true, '흥분하면 머리나 꼬리에서 불티가 날아올라 뜨거워진다. 왜인지 달콤한 것을 매우 좋아한다.', 'When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.'),
  ('unova', 41, 515, true, '머리의 송아리에 모은 물은 영양이 가득하다. 식물에 뿌려주면 크게 자란다.', 'The water stored inside the tuft on its head is full of nutrients. It waters plants with it using its tail.'),
  ('unova', 42, 516, true, '물이 깨끗한 장소를 좋아한다. 머리에 모아둔 물이 줄어들면 꼬리에서 빨아올려 보급한다.', 'It prefers places with clean water. When its tuft runs low, it replenishes it by siphoning up water with its tail.'),
  ('unova', 43, 543, true, '이빨에 맹독을 지녔다. 먹을 수 있는 먹이를 발견하면 앞뒤를 가리지 않고 덤벼든다.', 'Using the feelers on its head and tail, it picks up vibrations in the air to determine its prey’s location and state.'),
  ('unova', 44, 544, true, '단단한 껍질과 독가시로 몸을 보호하면서 진화에 필요한 에너지를 비축하고 있다.', 'Storing energy for evolution, it sits. But, when predators approach, it moves to stab them with poison spikes.'),
  ('unova', 45, 545, true, '영역을 두고 다태우지네와 격렬하게 다툰다. 패배한 쪽이 그대로 먹이가 된다.', 'It clasps its prey with the claws on its neck until it stops moving. Then it finishes it off with deadly poison.'),
  ('unova', 46, 109, true, '오염된 공기를 좋아한다. 옛날 가라르지방에는 지금보다 많은 또가스가 있었다고 한다.', 'Toxic gas is held within its thin, balloon-shaped body, so it can cause massive explosions.'),
  ('unova', 47, 110, true, '가라르의 또도가스보다 공기를 흡입하는 힘은 조금 약하지만 내뿜는 독소는 강력하다.', 'Inhaling toxic fumes from trash and mixing them inside its body lets it spread an even fouler stench.'),
  ('unova', 48, 81, true, '전기를 먹으며 살아간다. 좌우의 유닛에서 전기자석파를 방사하며 하늘을 난다.', 'The electromagnetic waves emitted by the units at the sides of its head expel antigravity, which allows it to float.'),
  ('unova', 49, 82, true, '강한 자력을 끊임없이 발산한다. 레어코일이 접근하면 대부분의 컴퓨터에 이상 현상이 발생한다.', 'The stronger electromagnetic waves from the three linked Magnemite are enough to dry out surrounding moisture.'),
  ('unova', 50, 462, true, '특수한 자기장의 영향으로 몸의 분자 구조가 변화해 진화했다고 여겨지고 있다.', 'Sometimes the magnetism emitted by Magnezone is too strong, making them attract each other so they cannot move.'),
  ('unova', 51, 58, true, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'Extremely loyal to its Trainer, it will bark at those who approach the Trainer unexpectedly and run them out of town.'),
  ('unova', 52, 59, true, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'The sight of it running over 6,200 miles in a single day and night has captivated many people.'),
  ('unova', 53, 240, true, '화산 주위에 살고 있다. 하루를 마칠 때에는 마그마에 잠겨 피로를 푼다.', 'It’s small, but its body temperature is over 1,100 degrees F. Embers escape its mouth and nose when it breathes.'),
  ('unova', 54, 126, true, '온몸이 늘 불타고 있다. 화재를 일으키는 원인 중 하나로 두려움의 대상이 되고 있다.', 'The scorching fire exhaled by Magmar forms heat waves around its body, making it hard to see the Pokémon clearly.'),
  ('unova', 55, 467, true, '화산의 화구에서 사는 동안 마그마 덩어리 모양의 기관을 가진 화산 같은 몸이 되었다.', 'When shooting 3,600 degree F fireballs from its arms, its body takes on a whitish hue from the intense heat.'),
  ('unova', 56, 239, true, '아직 전기를 모으는 게 서툴다. 전기를 먹기 위해 민가에 숨어들어 콘센트를 찾는다.', 'Spinning its arms around to generate electricity makes the area between its horns shine light blue.'),
  ('unova', 57, 125, true, '폭풍이 치면 높은 나무 주위에 모여 번개가 떨어지기를 가만히 기다린다.', 'Research is progressing on storing lightning in Electabuzz so this energy can be used at any time.'),
  ('unova', 58, 466, true, '발전량은 전기포켓몬 중에서도 손꼽히는 수준이다. 꼬리 끝에서 고압 전류를 방전한다.', 'The instant it presses the tips of its tails onto an opponent, it sends over 20,000 volts of electricity into the foe.'),
  ('unova', 59, 19, true, '2개의 이빨로 뭐든지 일단 갉고 본다. 1마리를 발견했다면 그곳에 40마리는 살고 있을 것이다.', 'It searches for food all day. It gnaws on hard objects to wear down its fangs, which grow constantly during its lifetime.'),
  ('unova', 60, 20, true, '뒷다리에 달린 작은 물갈퀴로 강을 헤엄치는 이유는 물속에 있는 먹이를 잡기 위해서다.', 'With its long fangs, this surprisingly violent Pokémon can gnaw away even thick concrete with ease.'),
  ('unova', 61, 41, true, '볕이 들지 않는 동굴에 산다. 아침이 되면 동료들끼리 모여 서로의 온기를 나누면서 잔다.', 'It does not need eyes, because it emits ultrasonic waves to check its surroundings while it flies.'),
  ('unova', 62, 42, true, '작은 다리로 능숙하게 걷는다. 자고 있는 먹이에게 살며시 다가가 이빨을 꽂아 피를 빨아먹는다.', 'Flitting around in the dead of night, it sinks its fangs into its prey and drains a nearly fatal amount of blood.'),
  ('unova', 63, 169, true, '4장의 날개를 자유자재로 움직이며 날갯짓한다. 좁은 동굴에서도 속도를 늦추지 않고 날아다닐 수 있다.', 'Having four wings allows it to fly more quickly and quietly so it can sneak up on prey without its noticing.'),
  ('unova', 64, 88, true, '진흙이 뭉쳐져서 태어났다. 악취 때문에 건드릴 엄두가 안 나고 지나간 자리에는 풀 한 포기 나지 않는다.', 'Born from sludge, these Pokémon now gather in polluted places and increase the bacteria in their bodies.'),
  ('unova', 65, 89, true, '악취가 심하다! 기절할 정도로 강렬하지만 질뻐기는 코가 퇴화해서 냄새를 맡지 못한다.', 'It’s so stinky! Muk’s body contains toxic elements, and any plant will wilt when it passes by.'),
  ('unova', 66, 527, true, '초음파를 발산하면서 흔들흔들 날아다닌다. 먹이인 벌레포켓몬을 찾고 있다.', 'The heart-shaped mark left on a body after a Woobat has been attached to it is said to bring good fortune.'),
  ('unova', 67, 528, true, '코의 모양이 복스럽다고 행복을 부르는 상징으로 여기는 지역도 있다고 한다.', 'It shakes its tail vigorously when it emits ultrasonic waves strong enough to reduce concrete to rubble.'),
  ('unova', 68, 524, true, '소리에 반응해 움직인다. 에너지 코어의 영향으로 만지면 조금 따듯하다.', 'The hexagonal-shaped hole is its ear. It has a tendency to walk in the direction the sound is coming from.'),
  ('unova', 69, 525, true, '소리로 주위 상황을 살핀다. 화나게 하면 몸의 방향을 바꾸지 않은 채로 쫓아온다.', 'When it is healthy, its core sticks out. Always facing the same way, it swiftly moves front to back and left to right.'),
  ('unova', 70, 526, true, '맑은 날에만 쏠 수 있지만 에너지탄의 파괴력은 덤프트럭도 날려버릴 정도다.', 'The solar rays it absorbs are processed in its energy core and fired as a ball of light.'),
  ('unova', 71, 95, true, '크고 튼튼한 몸을 뒤틀고 꼬아서 시속 80km로 힘차게 땅을 파나간다.', 'Opening its large mouth, it ingests massive amounts of soil and creates long tunnels.'),
  ('unova', 72, 208, true, '흙과 함께 삼킨 강철이 축적되어 몸이 변화한 것이라 여겨지고 있다.', 'The iron it ingested with the soil it swallowed transformed its body and made it harder than diamonds.'),
  ('unova', 73, 532, true, '자신의 3배 정도의 각목을 들 수 있게 된 으랏차는 머지않아 진화하게 된다.', 'Always carrying squared logs, they help out with construction. As they grow, they carry bigger logs.'),
  ('unova', 74, 533, true, '철골을 자유자재로 다룬다. 해체는 잘하지만 무언가를 조립하는 것은 서툴다.', 'With strengthened bodies, they skillfully wield steel beams to take down buildings.'),
  ('unova', 75, 534, true, '정말 싸울 생각이면 콘크리트 기둥을 버리고 주먹 하나로 상대를 노리고 덤벼든다.', 'Rather than rely on force, they master moves that utilize the centrifugal force of spinning concrete.'),
  ('unova', 76, 529, true, '손톱으로 땅속을 파고 다니면서 키우는 채소를 해치기 때문에 농업 종사자들이 싫어한다.', 'By spinning its body, it can dig straight through the ground at a speed of 30 mph.'),
  ('unova', 77, 530, true, '별명은 드릴킹이다. 땅속을 파는 속도는 시속 150km에 달한다.', 'Forming a drill with its steel claws and head, it can bore through a steel plate, no matter how thick it is.'),
  ('unova', 78, 300, true, '자신의 꼬리를 쫓아다니는 포켓몬이다. 야생에서는 숲의 나무 구멍에서 산다. 귀염성 있는 얼굴 때문에 애완동물로 인기가 높다.', 'It shows its cute side by chasing its own tail until it gets dizzy.'),
  ('unova', 79, 301, true, '일정한 거처 없이 생활하는 포켓몬이다. 다른 포켓몬이 잠자리에 가까이 다가와도 절대 다투지 않고 이동하여 잔다.', 'The reason it does not have a nest is that it simply searches for a clean, comfortable place then sleeps there.'),
  ('unova', 80, 427, true, '말고 있던 귀를 뻗는 힘으로 공격하는 기술은 트레이닝을 할수록 위력이 커진다.', 'By extending its rolled-up ears and striking the ground, it can bound so high it surprises itself.'),
  ('unova', 81, 428, true, '더운 계절이 끝나면 공기를 많이 머금은 털로 털갈이를 하여 추위에 대비한다.', 'Extremely cautious, it quickly bounds off when it senses danger.'),
  ('unova', 82, 546, true, '소미안과 백솜모카의 솜을 섞어 짠 천은 아름다워서 고급 브랜드에 사용된다.', 'Perhaps because they feel more at ease in a group, they stick to others they find. They end up looking like a cloud.'),
  ('unova', 83, 547, true, '햇빛을 받을수록 솜이 부풀어 오른다. 너무 부풀면 찢어져 주위로 흩어진다.', 'They appear along with whirlwinds. They pull pranks, such as moving furniture and leaving balls of cotton in homes.'),
  ('unova', 84, 548, true, '잎사귀의 색이 짙을수록 건강하다. 잘 정돈된 밭이나 화단에 자리잡고 살기도 한다.', 'The leaves on its head grow right back even if they fall out. These bitter leaves refresh those who eat them.'),
  ('unova', 85, 549, true, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'The fragrance of the garland on its head has a relaxing effect, but taking care of it is very difficult.'),
  ('unova', 86, 517, true, '꿈을 먹고 연기를 내뿜는다. 즐거운 꿈이면 핑크색이고 악몽이면 거무스름하다.', 'This Pokémon appears before people and Pokémon who are having nightmares and eats those dreams.'),
  ('unova', 87, 518, true, '언제나 선잠을 자며 꿈을 꾼다. 잠에서 깨면 매우 불쾌해하므로 가만히 내버려 두자.', 'The dream mist coming from its forehead changes into many different colors depending on the dream that was eaten.'),
  ('unova', 88, 173, true, '실루엣이 별 모양이다. 그 때문에 별똥별을 타고 온다고 여겨진다.', 'According to local rumors, Cleffa are often seen in places where shooting stars have fallen.'),
  ('unova', 89, 35, true, '애교 있는 몸동작과 울음소리로 귀엽다고 많은 인기를 누리는 포켓몬. 그러나 좀처럼 눈에 띄지 않는다.', 'On nights with a full moon, Clefairy gather from all over and dance. Bathing in moonlight makes them float.'),
  ('unova', 90, 36, true, '1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.', 'Their ears are sensitive enough to hear a pin drop from over a mile away, so they’re usually found in quiet places.'),
  ('unova', 91, 133, true, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'Thanks to its unstable genetic makeup, this special Pokémon conceals many different possible evolutions.'),
  ('unova', 92, 134, true, '몸의 세포 구조가 물 분자와 닮았다. 물에 녹으면 보이지 않는다.', 'Its cell composition is similar to water molecules. As a result, it can’t be seen when it melts away into water.'),
  ('unova', 93, 135, true, '공기 중의 마이너스 이온을 빨아들여 약 10000볼트의 전기를 내뱉을 수 있다.', 'By storing electricity in its body, it can shoot its bristlelike fur like a barrage of missiles.'),
  ('unova', 94, 136, true, '들이마신 공기 중 일부는 체내의 불꽃 주머니로 보내져 1700도의 불꽃이 된다.', 'Inhaled air is carried to its flame sac, heated, and exhaled as fire that reaches over 3,000 degrees F.'),
  ('unova', 95, 196, true, '이마의 구슬에서 사이코 파워를 방사해서 싸운다. 파워가 다하면 구슬의 색이 흐려진다.', 'Its fur is so sensitive, it can feel minute shifts in the air and predict the weather...and its foes’ thoughts.'),
  ('unova', 96, 197, true, '보름달이 뜬 밤이나 흥분했을 때 전신의 고리 무늬가 노랗게 빛난다.', 'When exposed to the moon’s aura, the rings on its body glow faintly and it’s filled with a mysterious power.'),
  ('unova', 97, 470, true, '꼬리는 날카로운 칼날 같다. 큰 나무도 두 동강 내는 탁월한 예리함을 자랑한다.', 'With cells similar to those of plants, it performs photosynthesis inside its body and creates pure air.'),
  ('unova', 98, 471, true, '글레이시아가 발산하는 냉기는 가루눈을 만들어 내기 때문에 스키장에서 인기가 높다.', 'It lowers its body heat to freeze its fur. The hairs then become like needles it can fire.'),
  ('unova', 99, 551, true, '작지만 하체의 힘은 세다. 모래를 헤치며 사막을 헤엄치듯 이동한다.', 'They live hidden under hot desert sands in order to keep their body temperature from dropping.'),
  ('unova', 100, 552, true, '어둠 속에서도 볼 수 있는 특수한 눈을 가졌지만 사막의 밤은 춥기 때문에 잘 움직이지 않는다.', 'Protected by thin membranes, their eyes can see even in the dead of night. They live in groups of a few individuals.'),
  ('unova', 101, 553, true, '난폭하지만 먹이를 잡기 위해 모래 속에서 며칠이든 기다리는 강한 인내력도 갖고 있다.', 'Very violent Pokémon, they try to clamp down on anything that moves in front of their eyes.'),
  ('unova', 102, 554, true, '자고 있을 때는 밀어도 당겨도 절대 쓰러지지 않는다. 길조의 모티브로 인기가 높다.', 'When it sleeps, it pulls its limbs into its body and its internal fire goes down to 1,100° F.'),
  ('unova', 103, 555, true, '체내의 불꽃이 타오를수록 파워가 올라간다. 그 온도는 1400도를 넘기도 한다.', 'When one is injured in a fierce battle, it hardens into a stone-like form. Then it meditates and sharpens its mind.'),
  ('unova', 103, 10067, false, '체내의 불꽃이 타오를수록 파워가 올라간다. 그 온도는 1400도를 넘기도 한다.', 'When one is injured in a fierce battle, it hardens into a stone-like form. Then it meditates and sharpens its mind.'),
  ('unova', 104, 550, true, '옛날에는 식탁에 올랐다. 적색근 배쓰나이의 살코기는 기름이 많아 젊은 층이 좋아한다.', 'Red- and blue-striped Basculin are very violent and always fighting. They are also remarkably tasty.'),
  ('unova', 104, 10066, false, '옛날에는 식탁에 올랐다. 적색근 배쓰나이의 살코기는 기름이 많아 젊은 층이 좋아한다.', 'Red- and blue-striped Basculin are very violent and always fighting. They are also remarkably tasty.'),
  ('unova', 105, 568, true, '쓰레기가 가득 담긴 쓰레기봉투에서 태어났다. 내뿜는 독가스는 가라르의 또도가스가 매우 좋아한다.', 'Wanting more garbage, they follow people who litter. They always belch poison gas.'),
  ('unova', 106, 569, true, '오른팔에서 내보내는 독액은 약한 생물이 맞으면 즉사할 정도로 위험하다.', 'Consuming garbage makes new kinds of poison gases and liquids inside their bodies.'),
  ('unova', 107, 572, true, '꼬리로 쓰다듬으며 서로 인사한다. 꼬리 털이 많은 쪽이 조금 으스댄다.', 'Minccino greet each other by grooming one another thoroughly with their tails.'),
  ('unova', 108, 573, true, '특별한 기름이 스며든 털은 공격을 받아넘긴다. 기름은 높은 가격에 거래되고 있다.', 'Cinccino’s body is coated in a special oil that helps it deflect attacks, such as punches.'),
  ('unova', 109, 627, true, '딱딱한 나무열매도 산산조각 내는 악력을 가졌다. 쉽게 다투고 아무에게나 승부를 건다.', 'It stands up to massive opponents, not out of courage, but out of recklessness. But that is how it gets stronger.'),
  ('unova', 110, 628, true, '혈기왕성하고 거칠어서 가라르의 배달부 자리는 아머까오에게 뺏겼다.', 'For the sake of its friends, this brave warrior of the sky will not stop battling, even if injured.'),
  ('unova', 111, 629, true, '금방 크게 성장하므로 엉덩이의 해골은 둥지 안에서 대물림되어 계속 사용된다.', 'Their wings are too tiny to allow them to fly. They guard their posteriors with bones that were gathered by Mandibuzz.'),
  ('unova', 112, 630, true, '주운 뼈로 몸을 장식한다. 몸에 두르는 뼈의 모양은 유행이 있는 듯하다.', 'They fly in circles around the sky. When they spot prey, they attack and carry it back to their nest with ease.'),
  ('unova', 113, 27, true, '땅을 파서 굴을 만든다. 땅속의 단단한 바위도 날카로운 발톱으로 부수며 파고들어 간다.', 'It digs deep burrows to live in. When in danger, it rolls up its body to withstand attacks.'),
  ('unova', 114, 28, true, '날카로운 발톱으로 찍으며 나무에 오른다. 아래에서 기다리는 모래두지들에게 나무열매를 떨어뜨려 나눠준다.', 'The spikes on its body are made up of its hardened hide. It rolls up and attacks foes with its spikes.'),
  ('unova', 115, 557, true, '집으로 삼기 딱 좋은 돌멩이를 발견하지 못하면 하마돈의 구멍에 살기도 한다.', 'When it finds a stone of a suitable size, it secretes a liquid from its mouth to open up a hole to crawl into.'),
  ('unova', 116, 558, true, '두꺼운 발톱이 최고의 무기다. 거대코뿌리의 프로텍터조차 금이 갈 정도로 딱딱하다.', 'When its boulder is broken in battles for territory, it feels unsure and begins to weaken.'),
  ('unova', 117, 559, true, '튼튼한 가죽으로 몸을 지킨다. 가죽이 다 늘어나면 진화할 때가 되었다고 한다.', 'Proud of its sturdy skull, it suddenly headbutts everything, but its weight makes it unstable, too.'),
  ('unova', 118, 560, true, '매우 거친 성격이지만 가족과 동료와 영역은 소중히 여긴다.', 'It pulls up its shed skin to protect itself while it kicks. The bigger the crest, the more respected it is.'),
  ('unova', 119, 556, true, '일 년에 한 번 씨를 뿌린다. 꽃의 씨는 영양이 매우 풍부해 사막의 귀중한 식량이다.', 'When it moves rhythmically, it makes a sound similar to maracas, making the surprised Pokémon flee.'),
  ('unova', 120, 561, true, '심보러가 나는 사막 아래를 조사해 보니 고대 도시로 여겨지는 자취가 발견되었다.', 'The guardians of an ancient city, they always fly the same route while keeping watch for invaders.'),
  ('unova', 121, 328, true, '절대 탈출 불가능한 원뿔형의 둥지를 만들어 먹이가 떨어지는 것을 기다린다.', 'It makes an inescapable conical pit and lies in wait at the bottom for prey to come tumbling down.'),
  ('unova', 122, 329, true, '날개를 성장시키기 위해 매일 대량의 먹잇감을 소화액으로 녹여 마신다.', 'The ultrasonic waves it generates by rubbing its two wings together cause severe headaches.'),
  ('unova', 123, 330, true, '날갯짓하는 소리가 여성의 아름다운 노랫소리와 닮아서 사막의 정령이라고 불린다.', 'Known as “The Desert Spirit,” this Pokémon hides in the sandstorms it causes by beating its wings.'),
  ('unova', 124, 562, true, '고대인의 영혼이 포켓몬이 되어 태어났다. 자신의 얼굴을 아는 사람을 찾아 유적을 떠돈다.', 'These Pokémon arose from the spirits of people interred in graves. Each retains memories of its former life.'),
  ('unova', 125, 563, true, '오래된 묘지의 벽을 보면 왕의 부를 드러내고자 그려져 있는 경우가 많다.', 'Grave robbers who mistake them for real coffins and get too close end up trapped inside their bodies.'),
  ('unova', 126, 564, true, '많은 거북포켓몬의 선조로 여겨지고 있는 포켓몬이다. 화석에서 복원되었다.', 'This Pokémon was restored from a fossil. It swam skillfully and dove to depths beyond half a mile.'),
  ('unova', 127, 565, true, '물속과 비교하면 움직임이 둔하지만 먹이를 찾아 육지에서도 활동한다.', 'It could knock out a foe with a slap from one of its developed front appendages and chew it up, shell or bones and all.'),
  ('unova', 128, 566, true, '새포켓몬의 선조로 불린다. 나무 위에서 살며 나무열매나 벌레포켓몬을 먹는다.', 'It was revived from an ancient fossil. Not able to fly, it lived in treetops and hopped from one branch to another.'),
  ('unova', 129, 567, true, '비행도 가능하지만 지상에서 먹이를 사냥하는 일을 훨씬 더 잘하는 듯하다.', 'It runs better than it flies. It takes off into the sky by running at a speed of 25 mph.'),
  ('unova', 130, 599, true, '먼 옛날에 기어르를 본 사람이 톱니바퀴의 구조를 고안했다고 전해진다.', 'Two bodies comprise a fixed pair. They spin around each other to generate energy.'),
  ('unova', 131, 600, true, '공업 기술의 상징으로 많은 가라르의 회사에서 기업 로고로 채용하고 있다.', 'A minigear and big gear comprise its body. If the minigear it launches at a foe doesn’t return, it will die.'),
  ('unova', 132, 601, true, '3개의 기어가 고속 회전한다. 가시가 달려 있는 새로 생긴 기어는 생물이 아니다.', 'The minigear spins at high speed. Then the energy from the red core charges the minigear to make it ready to fire.'),
  ('unova', 133, 406, true, '기온 변화에 민감하다. 봉오리가 피기 시작하면 곧 봄이 온다.', 'Sensitive to changing temperatures, the bud blooms when it’s warm, releasing toxic pollen.'),
  ('unova', 134, 315, true, '오른손과 왼손으로 2종류의 독을 구별하여 공격한다. 향기가 강할수록 기운이 넘친다.', 'It uses the different poisons in each hand separately when it attacks. The stronger its aroma, the healthier it is.'),
  ('unova', 135, 407, true, '오른손의 독은 즉효성이고 왼손의 독은 지효성을 띠고 있다. 양쪽 모두 생명에 지장을 준다.', 'Luring prey with a sweet scent, it uses poison whips on its arms to poison, bind, and finish off the prey.'),
  ('unova', 136, 574, true, '아무도 없는데 나직이 운다. 고디탱에게만 보이는 뭔가와 이야기하는 듯하다.', 'It stares intently at everything. It can become so obsessed with watching that it doesn’t notice attacks.'),
  ('unova', 137, 575, true, '별이 빛나는 밤에 가장 사이코 파워가 높아지는 듯하다. 우주와의 관계는 불명확하다.', 'According to many old tales, it creates friends for itself by controlling sleeping children on starry nights.'),
  ('unova', 138, 576, true, '고디모아젤을 통해 자신의 최후를 보게 된 악인은 그날을 마지막으로 종적을 감추었다.', 'It can see the future from the movement of the stars. When it learns its Trainer’s life span, it cries in sadness.'),
  ('unova', 139, 577, true, '특수한 액체로 몸을 둘러싸고 있어 우주에서도 살 수 있다고 전해진다.', 'Because their bodies are enveloped in a special liquid, they are fine in any environment, no matter how severe.'),
  ('unova', 140, 578, true, '분열한 2개의 뇌는 생각이 거의 일치하지 않아 전혀 행동을 예측할 수 없다.', 'When their two divided brains think the same thoughts, their psychic power is maximized.'),
  ('unova', 141, 579, true, '특수한 액체를 마시면 지혜를 얻는다고 전해지지만 란쿨루스 외에는 맹독이다.', 'They use psychic power to control their arms, which are made of a special liquid. They can crush boulders psychically.'),
  ('unova', 142, 415, true, '새벽부터 저녁때까지 꿀을 계속 모은다. 모든 것은 무리와 비퀸을 위해서다.', 'This Pokémon is a set of three. When they sleep, they gather up and form a giant hive of 100 Combee.'),
  ('unova', 143, 416, true, '페로몬을 발산하는 양이 많은 비퀸일수록 많은 세꿀버리를 거느리고 있다.', 'It houses its colony in cells in its body and releases various pheromones to make those grubs do its bidding.'),
  ('unova', 144, 587, true, '달콤한 나무열매를 매우 좋아한다. 볼주머니에 먹이를 너무 많이 넣어 잘 날지 못할 때도 있다.', 'It glides on its outstretched membrane while shocking foes with the electricity stored in the pouches on its cheeks.'),
  ('unova', 145, 214, true, '자신 몸무게의 100배에 달하는 무게도 거뜬히 들어 올리는 괴력을 자랑하는 포켓몬이다.', 'No matter how heavy its opponents, it flings them far away with its prized horn.'),
  ('unova', 146, 127, true, '뿔로 먹이를 찔러 넣어 그대로 두 동강으로 만들거나 강제로 던져버린다.', 'It grips prey with its powerful pincers and will not let go until the prey is torn in half.'),
  ('unova', 147, 522, true, '방전하면 갈기가 빛난다. 갈기가 빛나는 횟수나 리듬으로 동료와 대화한다.', 'Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.'),
  ('unova', 148, 523, true, '천둥번개 같은 순발력을 가지고 있다. 제브라이카가 전속력으로 달리면 천둥소리가 울려 퍼진다.', 'When this ill-tempered Pokémon runs wild, it shoots lightning from its mane in all directions.'),
  ('unova', 149, 418, true, '목의 부낭을 부풀려 수면에서 얼굴을 내밀어 주변의 상황을 살피고 있다.', 'It inflates the flotation sac around its neck and pokes its head out of the water to see what is going on.'),
  ('unova', 150, 419, true, '수중의 먹이를 쫓아가는 사이에 부낭이 발달했다. 고무보트처럼 사람을 태운다.', 'It is a common sight around fishing ports. It is known to rescue people and carry off prey.'),
  ('unova', 151, 570, true, '먹이를 찾아 사람으로 둔갑하여 마을에 나타나기도 한다. 주로 아이로 둔갑한다.', 'It changes so it looks just like its foe, tricks it, and then uses that opportunity to flee.'),
  ('unova', 152, 571, true, '고독한 트레이너는 조로아크에게 환상을 보여주도록 명령하여 혼자만의 외로움을 달랜다.', 'Stories say those who tried to catch Zoroark were trapped in an illusion and punished.'),
  ('unova', 153, 580, true, '나는 것보다 헤엄치는 것이 특기로 수중에 잠수해서는 제일 좋아하는 물이끼를 기쁘게 먹는다.', 'They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.'),
  ('unova', 154, 581, true, '새벽이 오면 스완나들이 춤추기 시작한다. 한가운데에서 춤추는 스완나가 무리의 우두머리다.', 'Despite their elegant appearance, they can flap their wings strongly and fly for thousands of miles.'),
  ('unova', 155, 588, true, '입에서 내뿜는 액체로 쪼마리의 껍질을 녹여서 내용물만 먹어 치운다.', 'For some reason they evolve when they receive electrical energy while they are attacking Shelmet.'),
  ('unova', 156, 589, true, '창을 겨누고 적에게 돌격한다. 창파나이트와의 결투를 그린 그림이 유명하다.', 'Wearing the shell covering they stole from Shelmet, they defend themselves and attack with two lances.'),
  ('unova', 157, 616, true, '전기 에너지에 반응하는 신비한 체질을 지녔다. 딱정곤과 함께 있으면 무슨 이유인지 진화한다.', 'When it and Karrablast are together, and both receive electrical stimulation, they both evolve.'),
  ('unova', 158, 617, true, '껍질을 벗어 몸이 가벼워졌다. 띠 형태의 점막을 몸에 둘러 건조해지는 것을 방지한다.', 'When its body dries out, it weakens. So it wraps a membrane around itself for protection while it spits poison.'),
  ('unova', 159, 585, true, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'Their coloring changes according to the seasons and can be slightly affected by the temperature and humidity as well.'),
  ('unova', 159, 10068, false, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'Their coloring changes according to the seasons and can be slightly affected by the temperature and humidity as well.'),
  ('unova', 159, 10069, false, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'Their coloring changes according to the seasons and can be slightly affected by the temperature and humidity as well.'),
  ('unova', 159, 10070, false, '계절이 바뀌는 시기가 되면 털과 냄새가 변화한다. 계절을 알리는 포켓몬이다.', 'Their coloring changes according to the seasons and can be slightly affected by the temperature and humidity as well.'),
  ('unova', 160, 586, true, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('unova', 160, 10071, false, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('unova', 160, 10072, false, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('unova', 160, 10073, false, '계절의 변화와 함께 거처를 바꾸기에 바라철록이 봄을 나른다고 말하는 사람도 있다.', 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
  ('unova', 161, 590, true, '양손에서 내뿜는 포자는 맹독이지만 잘 말리면 복통약이 된다고 한다.', 'It lures Pokémon with its pattern that looks just like a Poké Ball then releases poison spores.'),
  ('unova', 162, 591, true, '평상시에는 잘 움직이지 않는다. 떨어져 있는 몬스터볼 옆에서 그저 가만히 대기할 뿐이다.', 'It moves the caps on both arms and does a dance to lure prey. It prefers damp places.'),
  ('unova', 163, 351, true, '날씨에 따라 모습이 바뀐다. 날씨가 궂을수록 성질도 난폭해진다.', 'Temperature and weather affect its cellular structure, so this Pokémon changes form according to the weather.'),
  ('unova', 163, 10028, false, '날씨에 따라 모습이 바뀐다. 날씨가 궂을수록 성질도 난폭해진다.', 'Temperature and weather affect its cellular structure, so this Pokémon changes form according to the weather.'),
  ('unova', 163, 10029, false, '날씨에 따라 모습이 바뀐다. 날씨가 궂을수록 성질도 난폭해진다.', 'Temperature and weather affect its cellular structure, so this Pokémon changes form according to the weather.'),
  ('unova', 163, 10030, false, '날씨에 따라 모습이 바뀐다. 날씨가 궂을수록 성질도 난폭해진다.', 'Temperature and weather affect its cellular structure, so this Pokémon changes form according to the weather.'),
  ('unova', 164, 299, true, '강력한 자력으로 먹이를 끌어당겨 움직이지 않고 사냥을 하지만 천적을 끌어당기는 일도 있다.', 'Its magnetic nose always faces north and draws iron objects to its body to protect itself better.'),
  ('unova', 165, 476, true, '3개의 작은 유닛을 사용해서 먹이를 잡거나 적과 싸운다. 본체는 거의 명령할 뿐이다.', 'It freely controls three units called Mini-Noses using magnetic force.'),
  ('unova', 166, 304, true, '진화할 때 강철의 갑옷이 떨어진다. 옛날 사람들은 주워서 일상생활에서 유용하게 사용했다.', 'In order to build up its steel body, it eats iron ore. This pesky Pokémon is known to eat railroad tracks.'),
  ('unova', 167, 305, true, '서로 몸을 부딪치며 영역 싸움을 한다. 강철의 갑옷은 잘 보면 흠집과 파인 곳이 있다.', 'Lairon fight over territory, and when their steel bodies collide, sparks fly.'),
  ('unova', 168, 306, true, '먼 옛날 어떤 왕은 보스로라의 강함을 선망하여 머리 모양을 본떠 만든 투구를 쓰기도 했다.', 'It claims an entire mountain as its own. The more wounds it has, the more it has battled, so don’t take it lightly.'),
  ('unova', 169, 343, true, '고대 유적에서 발견되었다. 회전하면서 이동한다. 밤에 잘 때도 다리 하나로 서 있다.', 'Discovered in ancient ruins, it moves by spinning around and forms a group when it finds others.'),
  ('unova', 170, 344, true, '고대인의 진흙인형에서 태어난 것 같다. 염력을 사용해 공중을 떠다닌다.', 'This mysterious Pokémon started life as an ancient clay figurine made over 20,000 years ago.'),
  ('unova', 171, 636, true, '전신이 제법 따뜻하다. 뿔 끝에서 불꽃을 뿜어 천적이나 먹이를 위협한다.', 'Said to have been born from the sun, it spews fire from its horns and encases itself in a cocoon of fire when it evolves.'),
  ('unova', 172, 637, true, '활활 타오르는 불의 고치에서 태어났다. 고대의 벽화에 불꽃의 신으로 그려져 있다.', 'Thought to be an embodiment of the sun, it appeared during a bitterly cold winter and saved Pokémon from freezing.'),
  ('unova', 173, 595, true, '다른 포켓몬에게 달라붙어 정전기를 빨아들인다. 멍파치의 엉덩이에 자주 달라붙어 있다.', 'Since it can’t generate its own electricity, it sticks onto large-bodied Pokémon and absorbs static electricity.'),
  ('unova', 174, 596, true, '잘 날지 못하는 새끼를 노리고 새포켓몬 둥지 가까이에 전기로 된 실로 함정을 만든다.', 'It creates barriers from electrified silk that stun foes. This works as a weapon as well as a defense.'),
  ('unova', 175, 597, true, '이끼 낀 동굴을 좋아한다. 이끼에 함유된 효소가 가시를 크고 튼튼하게 만들어준다.', 'It absorbs the iron it finds in the rock while clinging to the ceiling. It shoots spikes when in danger.'),
  ('unova', 176, 598, true, '강철보다 견고한 가시를 갖고 있다. 촉수 가시를 찔러서 바위 벽을 기어 다니며 이동한다.', 'By swinging around its three spiky feelers and shooting spikes, it can obliterate an opponent.'),
  ('unova', 177, 602, true, '약한 전기밖에 낼 수 없어 많은 저리어가 모여서 강력한 전기를 발산한다.', 'One alone can emit only a trickle of electricity, so a group of them gathers to unleash a powerful electric shock.'),
  ('unova', 178, 603, true, '식욕이 왕성한 포켓몬이다. 먹이를 발견하면 덮쳐서 전기로 마비시킨 후 먹는다.', 'It wraps itself around its prey and paralyzes it with electricity from the round spots on its sides. Then it chomps.'),
  ('unova', 179, 604, true, '팔 힘으로 바다에서 기어 나와 물가에 있는 먹이를 덮친다. 한순간에 바다로 끌고 들어간다.', 'It latches on to prey with its sucker mouth, sinking in its fangs and shocking the prey with powerful electricity.'),
  ('unova', 180, 592, true, '해저에 가라앉은 고대 도시의 주민이 포켓몬이 되었다는 전설이 남아 있다.', 'If its veil-like arms stun and wrap a foe, that foe will be dragged miles below the surface, never to return.'),
  ('unova', 181, 593, true, '보름달이 뜨면 무리를 거느리고 해수면에 모습을 드러낸다. 먹이가 오기를 기다리는 것이다.', 'Its body is mostly seawater. It’s said there’s a castle of ships Jellicent have sunk on the seafloor.'),
  ('unova', 182, 594, true, '약해진 포켓몬을 도와주는 것은 이를 노리고 오는 포켓몬에게 자신도 공격받기 때문이라고 한다.', 'It gently holds injured and weak Pokémon in its fins. Its special membrane heals their wounds.'),
  ('unova', 183, 610, true, '커다란 어금니를 부딪치며 동료와 장난친다. 어금니는 부러져도 바로 자라나서 걱정 없다.', 'Its large tusks have a tendency to break, but each time they grow back, they grow in harder and sturdier.'),
  ('unova', 184, 611, true, '갑옷처럼 딱딱한 피부를 가졌다. 몸통박치기와 동시에 어금니로 찌르는 전법이 특기다.', 'A broken tusk will not grow back, so it diligently sharpens its tusks on river rocks after the end of a battle.'),
  ('unova', 185, 612, true, '온화한 성격이지만 화가 나면 무섭다. 철골도 베어 가르는 튼튼한 어금니를 보여 줄 것이다.', 'Its tusks are incredibly destructive. They can easily slice through a thick, sturdy steel column every time.'),
  ('unova', 186, 335, true, '평소에는 4개의 다리로 행동하지만 화나면 뒷다리로 서서 앞발의 발톱을 내보인다. 세비퍼와는 선조 대대로 라이벌이다.', 'It’s Seviper’s archrival. To threaten those it encounters, it fans out the claws on its front paws.'),
  ('unova', 187, 336, true, '칼과 같은 꼬리는 적을 베어 가르는 동시에 스며 나온 맹독을 끼얹는다. 숙적인 쟝고와 계속하여 싸운다.', 'Constant polishing makes the edge of the blade on its tail extremely sharp. It’s Zangoose’s archrival.'),
  ('unova', 188, 605, true, '약 50년 전에 발견된 포켓몬이다. 크게 발달한 뇌로 사이코 파워를 조종한다.', 'Rumors of its origin are linked to a UFO crash site in the desert 50 years ago.'),
  ('unova', 189, 606, true, '상대의 기억을 조작할 수 있다. 보리밭 위를 떠도는 모습이 가끔 목격된다.', 'Apparently, it communicates by flashing its three fingers, but those patterns haven’t been decoded.'),
  ('unova', 190, 607, true, '흡수하는 생명이 젊으면 젊을수록 머리의 불꽃은 크고 괴이하게 타오른다.', 'Its flame is usually out, but it starts shining when it absorbs life force from people or Pokémon.'),
  ('unova', 191, 608, true, '램프인 척 마을 안으로 숨어든다. 죽음이 다가온 사람을 발견하면 조용히 뒤를 쫓는다.', 'The spirits it absorbs fuel its baleful fire. It hangs around hospitals waiting for people to pass on.'),
  ('unova', 192, 609, true, '샹델라를 등불 대용으로 사용했던 저택에서는 장례식이 끊이지 않았다고 한다.', 'The spirits burned up in its ominous flame lose their way and wander this world forever.'),
  ('unova', 193, 631, true, '불꽃을 혀처럼 사용한다. 아이앤트의 단단한 외골격을 조금씩 녹여 먹어 치운다.', 'It draws in air through its tail, transforms it into fire, and uses it like a tongue. It melts Durant and eats them.'),
  ('unova', 194, 632, true, '큰 턱은 암석도 깨물어 부순다. 사다이사로부터 알을 지키기 위해 무리 지어 싸운다.', 'Individuals each play different roles in driving Heatmor, their natural predator, away from their colony.'),
  ('unova', 195, 613, true, '기술을 사용하기 전에 코를 훌쩍인다. 콧물에 포함된 강한 냉기가 얼음 기술의 근원이다.', 'Their snot is a barometer of health. When healthy, their snot is sticky and the power of their ice moves increases.'),
  ('unova', 196, 614, true, '차가운 바다에서 씩씩하게 헤엄친다. 지치면 한숨을 내쉬어 바다를 얼린 뒤 그 위에서 쉰다.', 'They love the cold seas of the north. They create pathways across the ocean waters by freezing their own breath.'),
  ('unova', 197, 615, true, '뜨거워지면 수증기로 변한다. 여름철에 모습을 볼 일은 거의 없다.', 'They are composed of ice crystals. They capture prey with chains of ice, freezing the prey at -148° F.'),
  ('unova', 198, 641, true, '토네로스의 꼬리에서 뿜어져 나온 에너지가 큰 폭풍을 일으킨다. 민가를 날려버릴 정도의 힘이다.', 'In every direction it flies, creating winds so powerful, they blow everything away.'),
  ('unova', 198, 10079, false, '토네로스의 꼬리에서 뿜어져 나온 에너지가 큰 폭풍을 일으킨다. 민가를 날려버릴 정도의 힘이다.', 'In every direction it flies, creating winds so powerful, they blow everything away.'),
  ('unova', 199, 642, true, '넓은 하늘을 날아다니며 여기저기 번개를 떨어뜨려 산불을 내기 때문에 미움받는다.', 'As it flies around, it shoots lightning all over the place and causes forest fires. It is therefore disliked.'),
  ('unova', 199, 10080, false, '넓은 하늘을 날아다니며 여기저기 번개를 떨어뜨려 산불을 내기 때문에 미움받는다.', 'As it flies around, it shoots lightning all over the place and causes forest fires. It is therefore disliked.'),
  ('unova', 200, 645, true, '바람이나 번개를 거둬들여 바꾼 에너지가 흙에 영양을 주어 대지를 풍족하게 한다.', 'From the forces of lightning and wind, it creates energy to give nutrients to the soil and make the land abundant.'),
  ('unova', 200, 10081, false, '바람이나 번개를 거둬들여 바꾼 에너지가 흙에 영양을 주어 대지를 풍족하게 한다.', 'From the forces of lightning and wind, it creates energy to give nutrients to the soil and make the land abundant.'),
  ('unova', 201, 451, true, '독이 있는 꼬리의 발톱으로 덤벼든다. 집히면 독이 스며들어 움직일 수 없게 된다.', 'It lives in arid regions and can go without food for a year while waiting for prey.'),
  ('unova', 202, 452, true, '사막의 악마라고 불릴 정도로 사납지만 하마돈에게는 싸움도 걸지 않고 얌전하다.', 'It takes pride in its strength. Even though it can tear foes apart, it finishes them off with powerful poison.'),
  ('unova', 203, 227, true, '빠진 깃털로 검을 만들 수 있어서 문장 도안으로 인기가 많다.', 'Its heavy-looking iron body is actually thin and light, so it can fly at speeds over 180 mph.'),
  ('unova', 204, 322, true, '1200도의 마그마를 몸에 저장하고 있다. 물에 젖으면 마그마가 식어서 덩어리져 무거워지므로 움직임이 둔해진다.', 'The magma in its body reaches 2,200 degrees F. Its hump gets smaller when it uses Fire-type moves.'),
  ('unova', 205, 323, true, '등의 혹은 뼈가 변형된 것이다. 펄펄 끓는 마그마를 가끔 뿜어 올린다. 화났을 때 자주 분화하는 것 같다.', 'The volcanoes on its back have a major eruption every 10 years--or whenever it becomes really angry.'),
  ('unova', 206, 325, true, '머리에 얹은 진주가 피그점프의 사이코 파워를 높여주는 역할을 한다. 항상 큰 진주를 찾고 있다.', 'Using its tail like a spring, it keeps its heart beating by bouncing constantly. If it stops, it dies.'),
  ('unova', 207, 326, true, '흑진주를 이용하여 이상한 힘을 사용할 때 기묘한 스텝으로 춤을 춘다. 흑진주는 미술품으로서의 가치를 지녔다.', 'It uses black pearls to amplify its psychic power. It does a strange dance to control foes’ minds.'),
  ('unova', 208, 425, true, '영혼들이 모여 탄생했다. 습기가 많은 계절에는 대량으로 나타나기도 한다.', 'These Pokémon are called the “Signpost for Wandering Spirits.” Children holding them sometimes vanish.'),
  ('unova', 209, 426, true, '사람과 포켓몬을 붙잡아 그대로 어딘가로 운반한다. 행선지는 아무도 모른다.', 'They carry people and Pokémon, but the wind can catch them, so there can’t be a fixed destination.'),
  ('unova', 210, 353, true, '해질녘에 어둠대신이 줄지어 있는 집과는 어울리지 말라는 오랜 속담이 남아 있다.', 'It feeds on the dark emotions of sadness and hatred, which make it grow steadily stronger.'),
  ('unova', 211, 354, true, '버려진 원념에 의해 태어난다. 소중히 대하면 만족해서 원래의 인형으로 돌아간다고 한다.', 'A doll that became a Pokémon over its grudge of being thrown away. It seeks the child who disowned it.'),
  ('unova', 212, 278, true, '공기의 흐름을 이용하여 날갯짓하지 않고 하늘로 날아오른다. 해변의 절벽에 둥지를 만든다.', 'It makes its nest on sheer cliffs. Riding the sea breeze, it glides up into the expansive skies.'),
  ('unova', 213, 279, true, '해면 아주 가까이 날아 큰 부리로 해수와 함께 먹이를 건져 나른다.', 'Skimming the water’s surface, it dips its large bill in the sea, scoops up food and water, and carries it.'),
  ('unova', 214, 337, true, '40년 전에 운석이 떨어진 장소에서 처음 발견되었다. 노려보기만 해도 적을 잠들게 한다.', 'The phase of the moon apparently has some effect on its power. It’s active on the night of a full moon.'),
  ('unova', 215, 338, true, '태양 에너지가 파워의 근원이라서 낮에는 강하다. 회전하면 몸이 빛난다.', 'Solar energy is the source of its power, so it is strong during the daytime. When it spins, its body shines.'),
  ('unova', 216, 359, true, '위험을 감지하는 능력이 있어 사람들로부터 재앙을 불러오는 포켓몬이라는 오해를 샀다.', 'It appears from deep in the mountains to warn people about upcoming disasters it has sensed with its horn.'),
  ('unova', 217, 114, true, '덩굴은 독특한 향이 난다. 가라르 일부 지역에서는 허브로 사용되고 있다.', 'Many writhing vines cover it, so its true identity remains unknown. The blue vines grow its whole life long.'),
  ('unova', 218, 465, true, '따듯한 땅에서 살수록 덩굴의 성장이 빠르다. 길어지면 스스로 잘라내어 짧게 만든다.', 'Even if one of its arms is eaten, it’s fine. The Pokémon regenerates quickly and will go right back to normal.'),
  ('unova', 219, 619, true, '작아도 기질은 거칠다. 방심하고 다가간 상대에게 화려한 연타를 먹인다.', 'It takes pride in the speed at which it can use moves. What it loses in power, it makes up for in quantity.'),
  ('unova', 220, 620, true, '눈에 보이지 않을 정도의 스피드로 구사하는 발차기는 거대한 바위도 산산이 조각낸다.', 'Using the long fur on its arms like whips, it launches into combo attacks that, once started, no one can stop.'),
  ('unova', 221, 207, true, '소리 내지 않고 미끄러지듯 활공한다. 양손의 커다란 손톱과 발의 발톱으로 먹이의 얼굴에 달라붙어 독침을 찌른다.', 'It clamps on to its chosen prey then jabs the stinger on its tail into the prey while it’s stunned with surprise.'),
  ('unova', 222, 472, true, '날갯소리를 내지 않고 하늘을 난다. 긴 꼬리로 먹이를 잡아 송곳니로 급소를 공격한다.', 'It dances silently through the sky. When it approaches prey, it can land a critical hit in an instant.'),
  ('unova', 223, 624, true, '절각참을 보스로 둔 무리를 만든다. 무리를 이끄는 날을 꿈꾸며 날마다 단련을 계속한다.', 'Ignoring their injuries, groups attack by sinking the blades that cover their bodies into their prey.'),
  ('unova', 224, 625, true, '칼날을 가는 돌의 장소를 두고 액슨도와 격렬하게 싸움을 벌인다.', 'This pitiless Pokémon commands a group of Pawniard to hound prey into immobility. It then moves in to finish the prey off.'),
  ('unova', 225, 638, true, '태어나면서부터 리더의 품격을 몸에 지녔다. 흉포한 상대도 코바르온의 앞에서는 온순하다.', 'It has a body and heart of steel. It worked with its allies to punish people when they hurt Pokémon.'),
  ('unova', 226, 639, true, '포켓몬을 지키기 위해 사람에게 승부를 걸었다는 전설이 하나지방에 남아 있다.', 'Spoken of in legend, this Pokémon used its phenomenal power to destroy a castle in its effort to protect Pokémon.'),
  ('unova', 227, 640, true, '회오리바람처럼 재빠른 몸동작으로 적을 농락하고 예리한 뿔로 가차 없이 베어버린다.', 'Legends say this Pokémon confounded opponents with its swift movements.'),
  ('unova', 228, 535, true, '음파로 동료와 연락한다. 경계하는 울음소리는 사람이나 다른 포켓몬에게 들리지 않는다.', 'By vibrating its cheeks, it emits sound waves imperceptible to humans and warns others of danger.'),
  ('unova', 229, 536, true, '고운 목소리로 울 때도 있다. 몸의 돌기가 클수록 넓은 음역으로 울 수 있다.', 'It lives in the water and on land. It uses its long, sticky tongue to immobilize its opponents.'),
  ('unova', 230, 537, true, '혹이 일으키는 바이브레이션이 마사지에 좋다고 노인에게 인기가 높은 포켓몬이다.', 'By putting power into its bumps, it creates vibrations and increases the power of its punches.'),
  ('unova', 231, 618, true, '몸의 노란 무늬에서 강한 전기를 발산할 때 무슨 이유인지 살짝 웃고 있다.', 'When its opponent can’t be paralyzed, it contorts itself with unexpected speed and flops away.'),
  ('unova', 232, 213, true, '항아리 같은 등껍질 속에 모은 나무열매는 어느샌가 걸쭉한 주스로 변한다.', 'The berries stored in its vaselike shell eventually become a thick, pulpy juice.'),
  ('unova', 233, 458, true, '총어 무리에 섞여서 헤엄친다. 적에게 습격당하면 무리와 함께 싸운다.', 'The pattern on its back varies by region. It often swims in a school of Remoraid.'),
  ('unova', 234, 226, true, '여유롭게 바다를 헤엄친다. 먹다 남은 음식을 노린 총어가 달라붙어 있어도 신경 쓰지 않는다.', 'If it builds up enough speed swimming, it can fly over 300 feet out of the water from the surface of the ocean.'),
  ('unova', 235, 223, true, '빨판처럼 변화한 등지느러미로 만타인에게 달라붙어 먹다 남은 것을 얻어먹고 있다.', 'The water they shoot from their mouths can hit moving prey from more than 300 feet away.'),
  ('unova', 236, 224, true, '머리가 돌처럼 단단하다. 빨판이 붙어 있는 다리를 휘감아 끊임없이 머리로 세게 때린다.', 'It has a tendency to want to be in holes. It prefers rock crags or pots and sprays ink from them before attacking.'),
  ('unova', 237, 222, true, '따뜻한 바다에 서식한다. 태고에는 가라르 근해에서도 많은 수가 서식했었다.', 'They prefer unpolluted southern seas. Their coral branches lose their color and deteriorate in dirty water.'),
  ('unova', 238, 120, true, '물고기포켓몬에게 물리곤 하지만 몸이 찢겨도 금방 재생되기 때문에 신경 쓰지 않는다.', 'As long as its red core remains, it can regenerate its body instantly, even if it’s torn apart.'),
  ('unova', 239, 121, true, '몸을 고속으로 회전시켜 바다를 헤엄치며 작은 플랑크톤을 흡수한다.', 'Its core shines in many colors and sends radio signals into space to communicate with something.'),
  ('unova', 240, 320, true, '바닷물을 많이 마시면 몸이 공처럼 튄다. 매일 1톤의 먹이를 먹는다.', 'It eats one ton of food every day. It plays by shooting stored seawater out its blowholes with great force.'),
  ('unova', 241, 321, true, '엄청나게 거대해서 인기가 있다. 고래왕 워칭은 각지에서 인기 있는 관광 코스다.', 'It can sometimes knock out opponents with the shock created by breaching and crashing its big body onto the water.'),
  ('unova', 242, 131, true, '추위에 강해서 얼음 바다에서도 끄떡없다. 피부는 매끈매끈하고 조금 차갑다.', 'Able to understand human speech and very intelligent, it loves to swim in the sea with people on its back.'),
  ('unova', 243, 363, true, '파도에 떠다니며 바다의 상태를 살핀다. 먹이를 발견하면 무리의 씨카이저에게 알린다.', 'They can’t swim well yet, and they move much faster by rolling. When they’re happy, they clap fins.'),
  ('unova', 244, 364, true, '대굴레오나 몬스터볼 등 둥근 것이라면 뭐든지 코 위에 올려놓고 돌리는 습성이 있다.', 'Be it Spheal or Poké Ball, it will spin any round object on its nose with the greatest of ease.'),
  ('unova', 245, 365, true, '이빨은 평생 자란다. 싸우다 부러져도 1년이 지나면 원래의 훌륭한 이빨로 복원된다.', 'Not only does its thick blubber keep it warm, it also protects it from attacks. It shatters ice with its prized tusks.'),
  ('unova', 246, 333, true, '솜구름처럼 보이기 때문에 적의 눈에 잘 띄지 않는다. 세대를 거치면서 날개가 하얗게 되었다고 한다.', 'For some reason, it likes to land on people’s heads softly and act like it’s a hat.'),
  ('unova', 247, 334, true, '온순한 성질이지만 화나게 하면 날카로운 울음소리로 위협하며 가차 없이 공격한다.', 'On sunny days, it flies freely through the sky and blends into the clouds. It sings in a beautiful soprano.'),
  ('unova', 248, 37, true, '6개의 꼬리는 자라면서 털의 결이 좋아지며 아름다워진다. 안으면 살짝 따듯하다.', 'As each tail grows, its fur becomes more lustrous. When held, it feels slightly warm.'),
  ('unova', 249, 38, true, '머리가 좋고 집념이 강하다. 장난으로 꼬리를 잡으면 1000년 동안 화를 입는다고 한다.', 'Each of its nine tails is imbued with supernatural power, and it can live for a thousand years.'),
  ('unova', 250, 436, true, '닦으면 빛이 나며 진실을 비춘다고 전해지지만 동미러는 닦이는 걸 매우 싫어한다.', 'They are found in ancient tombs. The patterns on their backs are said to be imbued with mysterious power.'),
  ('unova', 251, 437, true, '몸의 무늬 때문에 본래 가라르에는 없던 포켓몬이라고 생각하는 학자도 많다.', 'In ages past, this Pokémon was revered as a bringer of rain. It was found buried in the ground.'),
  ('unova', 252, 215, true, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'A smart and sneaky Pokémon, it makes its opponents flinch by suddenly showing the claws hidden in its paws.'),
  ('unova', 253, 461, true, '발톱으로 사인을 그려 동료와 연락한다. 사인의 종류는 500가지가 넘는다고 한다.', 'They communicate by clawing signs in boulders and work together to surround enemies.'),
  ('unova', 254, 225, true, '자신의 먹이를 사람이나 포켓몬에게 나눠주는 습성이 있어 언제나 먹이를 찾아다닌다.', 'It carries food all day long. When someone is lost in the mountains, it shares that food.'),
  ('unova', 255, 582, true, '고드름에서 태어났다고 전해진다. 마이너스 50도의 냉기를 뿜어 주변을 얼려 살기 좋게 만든다.', 'Theoretically, this Pokémon formed from icicles bathed in energy from the morning sun. Their breath is -58° F.'),
  ('unova', 256, 583, true, '마이너스 100도의 냉기로 적을 얼리지만 목숨은 뺏지 않는 상냥한 기질을 가졌다.', 'They cool down the surrounding air and create ice particles, which they use to freeze their foes.'),
  ('unova', 257, 584, true, '체온은 마이너스 6도 전후이다. 2마리의 바닐리치가 붙어서 태어났다고 한다.', 'Swallowing large amounts of water, they make snow clouds inside their bodies and, when angry, cause violent blizzards.'),
  ('unova', 258, 220, true, '좋은 냄새를 맡으면 뒷일을 생각하지 않고 냄새 나는 방향으로 대시해버린다.', 'Rooting the tip of its snout into the ground, it searches for food. Sometimes it even digs up a hot spring.'),
  ('unova', 259, 221, true, '4개의 다리는 짧지만 발굽이 넓고 거칠거칠하므로 눈 위도 미끄러지지 않고 걸을 수 있다.', 'With its excellent sense of smell, it’s even able to find mushrooms that are buried under frozen ground.'),
  ('unova', 260, 473, true, '생긴 것처럼 힘이 장사다. 얼음으로 된 엄니는 추울수록 굵고 길어지면서 늠름해진다.', 'When the temperature rose at the end of the ice age, most Mamoswine disappeared.'),
  ('unova', 261, 132, true, '메타몽끼리 만나게 되면 상대와 똑같은 모습이 되기 위해 평소보다 격렬하게 움직인다.', 'It can reconstitute its entire cellular structure to change into what it sees, but it returns to normal when it relaxes.'),
  ('unova', 262, 374, true, '몸의 세포가 자석으로 되어 있다. 혈액 대신에 자력이 온몸에 흐른다.', 'Its cells are all magnetic, and it communicates with others by using magnetic pulses.'),
  ('unova', 263, 375, true, '자력으로 하늘을 난다. 험준한 산들을 누비듯이 고속으로 비행하여 먹이를 쫓는다.', 'It is formed by two Beldum joining together. Its two brains are linked, amplifying its psychic power.'),
  ('unova', 264, 376, true, '2마리의 메탕구가 합체한 모습이다. 슈퍼컴퓨터 수준의 두뇌를 사용해 적을 쓰러뜨린다.', 'With four linked brains, it’s more intelligent than a supercomputer, and it uses calculations to analyze foes.'),
  ('unova', 265, 86, true, '얼어붙을 정도로 추운 곳을 좋아한다. 영하 10도 정도의 물속에서 기분 좋게 헤엄친다.', 'The colder it gets, the better it feels. It joyfully swims around oceans so cold that they are filled with floating ice.'),
  ('unova', 266, 87, true, '온몸이 눈처럼 새하얗다. 추위에 강해 얼음이 떠 있는 바다도 기운차게 헤엄쳐 다닌다.', 'Its streamlined body has low resistance, and it swims around cold oceans at a speed of eight knots.'),
  ('unova', 267, 538, true, '5마리의 무리가 수련한다. 수련에 뒤떨어지면 띠를 버리고 무리를 떠난다.', 'When it encounters a foe bigger than itself, it wants to throw it. It changes belts as it gets stronger.'),
  ('unova', 268, 539, true, '단련하고 단련한 타격귀가 사용하는 필살 태권당수는 바다도 가를 정도의 파괴력을 지녔다.', 'Desiring the strongest karate chop, they seclude themselves in mountains and train without sleeping.'),
  ('unova', 269, 626, true, '20마리 정도가 무리 지어 산다. 무리를 배신한 버프론은 어째서인지 머리털이 빠진다.', 'They are known to charge so wildly that if a train were to enter their territory, they would send it flying.'),
  ('unova', 270, 621, true, '난폭하고 교활하다. 다른 포켓몬이 파낸 굴을 빼앗아 거처로 삼는다.', 'It runs through the narrow tunnels formed by Excadrill and Onix. It uses its sharp claws to catch prey.'),
  ('unova', 271, 622, true, '점토로 만들어진 포켓몬이다. 수천 년 전 주인의 명령을 지금도 따르고 있다.', 'Ancient science fashioned this Pokémon from clay. It’s been active for thousands of years.'),
  ('unova', 272, 623, true, '체내에 에너지를 생성하는 영구 기관이 있다고 하지만 아직도 밝혀지지 않았다.', 'Golurk were created to protect people and Pokémon. They run on a mysterious energy.'),
  ('unova', 273, 633, true, '눈이 보이지 않아 닥치는 대로 물면서 본인 주위의 상황을 파악한다.', 'Lacking sight, it’s unaware of its surroundings, so it bumps into things and eats anything that moves.'),
  ('unova', 274, 634, true, '1개의 먹이를 2개의 머리가 서로 뺏는다. 누구랑 싸운 것도 아닌데 언제나 상처투성이다.', 'The two heads do not get along. Whichever head eats more than the other gets to be the leader.'),
  ('unova', 275, 635, true, '3개의 머리로 번갈아 가며 물어뜯는다. 상대가 쓰러질 때까지 공격을 멈추지 않는다.', 'It responds to movement by attacking. This scary, three-headed Pokémon devours everything in its path!'),
  ('unova', 276, 287, true, '심장의 고동이 1분에 1번 뛴다. 아무튼 가만히 누워 있는 포켓몬으로 움직이는 모습을 거의 볼 수가 없다.', 'If it eats just three leaves in a day, it is satisfied. Other than that, it sleeps for 20 hours a day.'),
  ('unova', 277, 288, true, '가만히 있질 못하는 포켓몬이다. 자려고 해도 몸의 피가 끓어올라서 숲 속을 뛰어다니지 않으면 가라앉지 않는다.', 'Its heartbeat is fast and its blood so agitated that it can’t sit still for one second.'),
  ('unova', 278, 289, true, '초원에 새겨진 반경 1m의 둥근 띠 모양은 게을킹이 누운 채로 주변의 풀을 먹어치워 생긴 것이다.', 'This Pokémon lives lying on its side. It only rolls over and moves when there is no more grass to eat.'),
  ('unova', 279, 341, true, '외국에서 온 포켓몬이 야생화했다. 아무리 더러운 강이라도 적응해버린다.', 'No matter how dirty the water in the river, it will adapt and thrive. It has a strong will to survive.'),
  ('unova', 280, 342, true, '싸움을 좋아하는 성격. 거처에 가까이 오는 상대를 가차 없이 때려눕힌다.', 'Loving to battle, this Pokémon pinches all Pokémon that enter its territory with its pincers and throws them out.'),
  ('unova', 281, 174, true, '부드러운 몸으로 통통 튀며 움직인다. 체온이 오르면 몸은 짙은 핑크색이 된다.', 'Its body has a faintly sweet scent and is bouncy and soft. If it bounces even once, it cannot stop.'),
  ('unova', 282, 39, true, '목소리 파장을 자유자재로 바꾸어 들으면 반드시 잠드는 신비한 멜로디를 노래한다.', 'Looking into its cute, round eyes makes it start singing a song so pleasant listeners can’t help but fall asleep.'),
  ('unova', 283, 40, true, '얇고 고운 털을 가졌다. 특히 이마에 동그랗게 말린 털은 하늘을 날 듯한 최고의 감촉을 지녔다.', 'Its fine fur feels so pleasant, those who accidentally touch it cannot take their hands away.'),
  ('unova', 284, 108, true, '벌레포켓몬이 주된 먹이다. 긴 혀로 상대를 핥아 마비시킨 후 통째로 삼킨다.', 'Being licked by its long, saliva-covered tongue leaves a tingling sensation. Extending its tongue retracts its tail.'),
  ('unova', 285, 463, true, '사람의 팔과 견줄 수 있을 정도의 활용도 높은 혀로 뭐든지 한다. 반대로 손은 무디다.', 'Their saliva contains lots of components that can dissolve anything. The numbness caused by their lick does not dissipate.'),
  ('unova', 286, 193, true, '눈알을 움직이지 않고 360도를 볼 수 있다. 급브레이크나 방향 전환이 특기다. 노린 먹이를 빠르게 몰아넣는다.', 'By flapping its wings at high speed, it can fly freely through the air. Even sudden stops are no problem.'),
  ('unova', 287, 469, true, '6개의 다리로 어른을 껴안고도 너끈히 날 수 있다. 꼬리의 날개로 균형을 잡는다.', 'It prefers to battle by biting apart foes’ heads instantly while flying by at high speed.'),
  ('unova', 288, 357, true, '목에 난 송이는 맛있어서 인기다. 따뜻한 장소에는 트로피우스를 키우는 목장이 많다.', 'It flies by flapping its broad leaves and gives the sweet, delicious fruit around its neck to children.'),
  ('unova', 289, 455, true, '늪지대에서 자라는 나무에 엉겨 붙어 달콤한 냄새의 타액으로 먹이를 끌어들여 한입에 먹는다.', 'Using its tentacles to lash itself to trees, it lies in wait for prey, luring it close with sweet-smelling drool.'),
  ('unova', 290, 453, true, '독을 희석하면 약이 된다. 제약 회사의 마스코트가 된 후로 인기가 많아졌다.', 'Inflating its poison sacs, it fills the area with an odd sound and hits flinching opponents with a poison jab.'),
  ('unova', 291, 454, true, '사냥감을 처리하면 개굴개굴하며 승리를 자축하는 소리를 높인다. 두빅굴과 가까운 종이다.', 'The croaking that Toxicroak produces before a battle is for churning the poison it has stored in its poison sac.'),
  ('unova', 292, 246, true, '흙을 먹으며 살고 있다. 큰 산 하나를 다 먹으면 성장을 위해 잠자기 시작한다.', 'Born deep underground, it comes aboveground and becomes a pupa once it has finished eating the surrounding soil.'),
  ('unova', 293, 247, true, '번데기지만 가만히 있지 않는다. 단단한 껍질 안에는 이미 팔다리가 만들어져 있다.', 'This pupa flies around wildly by venting with great force the gas pressurized inside its body.'),
  ('unova', 294, 248, true, '지축을 울리면서 걸으면 큰 산조차 무너지며 주변의 지형은 변해버린다.', 'The quakes caused when it walks make even great mountains crumble and change the surrounding terrain.'),
  ('unova', 295, 643, true, '사람이 진실을 모른 체하고 욕심으로 가득 차면 불꽃으로 나라를 태워버린다는 신화가 있다.', 'This legendary Pokémon can scorch the world with fire. It helps those who want to build a world of truth.'),
  ('unova', 296, 644, true, '사람이 올바른 마음을 잃으면 격렬한 천둥으로 나라를 멸망시킨다는 신화가 있다.', 'This legendary Pokémon can scorch the world with lightning. It assists those who want to build an ideal world.'),
  ('unova', 297, 646, true, '세포 조직을 안정시키기 위해 자신이 발생시킨 냉기로 몸을 얼어붙게 한 듯하다.', 'This legendary ice Pokémon waits for a hero to fill in the missing parts of its body with truth or ideals.'),
  ('unova', 297, 10082, false, '세포 조직을 안정시키기 위해 자신이 발생시킨 냉기로 몸을 얼어붙게 한 듯하다.', 'This legendary ice Pokémon waits for a hero to fill in the missing parts of its body with truth or ideals.'),
  ('unova', 297, 10083, false, '세포 조직을 안정시키기 위해 자신이 발생시킨 냉기로 몸을 얼어붙게 한 듯하다.', 'This legendary ice Pokémon waits for a hero to fill in the missing parts of its body with truth or ideals.'),
  ('unova', 298, 647, true, '혹독한 싸움을 이겨내고 이마의 뿔이 단련되면 진정한 힘이 각성한다고 한다.', 'When it is resolute, its body fills with power and it becomes swifter. Its jumps are then too fast to follow.'),
  ('unova', 298, 10084, false, '혹독한 싸움을 이겨내고 이마의 뿔이 단련되면 진정한 힘이 각성한다고 한다.', 'When it is resolute, its body fills with power and it becomes swifter. Its jumps are then too fast to follow.'),
  ('unova', 299, 648, true, '특수한 발성법으로 노래하는 멜로디는 노래를 들은 자의 감정을 자유자재로 조종한다.', 'The melodies sung by Meloetta have the power to make Pokémon that hear them happy or sad.'),
  ('unova', 299, 10074, false, '특수한 발성법으로 노래하는 멜로디는 노래를 들은 자의 감정을 자유자재로 조종한다.', 'The melodies sung by Meloetta have the power to make Pokémon that hear them happy or sad.'),
  ('unova', 300, 649, true, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('unova', 300, 10075, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('unova', 300, 10076, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('unova', 300, 10077, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
  ('unova', 300, 10078, false, '3억 년 전에 있었던 포켓몬. 플라스마단에게 개조당해 등에 대포가 붙여졌다.', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.')
on conflict (dex, species_id) do update set
